},\n      \"vulnerable_version_range\": \">= 1.92.0, < 1.92.2\",\n      \"first_patched_version\": \"1.92.2\",\n      \"vulnerable_functions\": []\n    },\n    {\n      \"package\": {\n        \"ecosystem\": \"pip\",\n        \"name\": \"litellm\"\n      },\n      \"vulnerable_version_range\": \">= 1.93.0, < 1.93.2\",\n      \"first_patched_version\": \"1.93.2\",\n      \"vulnerable_functions\": []\n    },\n    {\n      \"package\": {\n        \"ecosystem\": \"pip\",\n        \"name\": \"litellm\"\n      },\n      \"vulnerable_version_range\": \">= 1.94.0, < 1.94.3\",\n      \"first_patched_version\": \"1.94.3\",\n      \"vulnerable_functions\": []\n    },\n    {\n      \"package\": {\n        \"ecosystem\": \"pip\",\n        \"name\": \"litellm\"\n      },\n      \"vulnerable_version_range\": \">= 1.95.0, < 1.95.1\",\n      \"first_patched_version\": \"1.95.1\",\n      \"vulnerable_functions\": []\n    },\n    {\n      \"package\": {\n        \"ecosystem\": \"pip\",\n        \"name\": \"litellm\"\n      },\n      \"vulnerable_version_range\": \">= 1.96.0, < 1.96.2\",\n      \"first_patched_version\": \"1.96.2\",\n      \"vulnerable_functions\": []\n    }\n  ],\n  \"cvss_severities\": {\n    \"cvss_v3\": {\n      \"vector_string\": \"CVSS:3.1/AV:N/AC:L/PR:L/UI:N/S:U/C:H/I:N/A:N\",\n      \"score\": 6.5\n    },\n    \"cvss_v4\": {\n      \"vector_string\": null,\n      \"score\": 0.0\n    }\n  },\n  \"cwes\": [\n    {\n      \"cwe_id\": \"CWE-918\",\n      \"name\": \"Server-Side Request Forgery (SSRF)\"\n    }\n  ],\n  \"credits\": [],\n  \"comments\": 1,\n  \"epss\": {\n    \"percentage\": 0.0054,\n    \"percentile\": 0.42932\n  }\n}\n","exit_code":0,"status":"completed"}}
