ects/fa/26c52ea3eba4af8f815103c89b2bb2e3129b19\": \"a1550e04bbc5b2b220920f6de6041eab48da34f148ce3bc76dd1d8f51b9f94b0\",\n      \"objects/be/e6e4521b68ea6ccc976ad71c06ef2aa8b49b75\": \"e069a7116b9f18a8bbce013fdbfae03af71cb0fc373568ea80613d909e76a04b\",\n      \"objects/be/6fdafc20a373ba8ea4a29bedb4e4fffccca71e\": \"17885db9cd52b87732c20cbdb9242d056fa95964a187ef1387d7b791f17c8f4e\",\n      \"objects/5b/231ee7bf90824d56ca32d9339a2b0f45b58618\": \"bc4f2f6709156f286dd93e4c3d8adf4a192a4255bfb94c4990d5c3138092aa49\",\n      \"objects/pack/pack-77494ba533d023728d54b3dd91de53a8aeb290f8.pack\": \"7753be1e51cf85f934f0757a9da5ca774b62c1bb238afd0c6e6245283bb7670b\",\n      \"objects/pack/pack-77494ba533d023728d54b3dd91de53a8aeb290f8.idx\": \"d650bab4acb4a8c8d6d523dbe0c21dc183c0018df6cdc05f879a26a276997374\",\n      \"objects/pack/pack-77494ba533d023728d54b3dd91de53a8aeb290f8.rev\": \"92fbd3abd1dad104e23dda23407d896f9bc666994d79244efb3f3ec496661bae\",\n      \"objects/b7/c77b06c75e822c7b209f6c840798357579f6b9\": \"007775345ac2158f06dd9034df1c0c5eb2dedfa55fc8d317b41502519edc3cd8\",\n      \"objects/b7/47d09ac26bf4b459b28bfd79fc75b2c4de107f\": \"e03f13cb52160a08926ee57f5c151207b39340eefcc10beff96d7c72aaa42e86\",\n      \"objects/30/f66fd7083a44f0d3f22cf14b26f8625804a43e\": \"7d9cdf5f5cd7cf2bc612e9b97e6b1a42a0f8906b211490e239e3a017ec5557d5\",\n      \"objects/ad/ed015fbe17da235052263dbad11d0736110663\": \"3ab684a20e27ab9e62dc016cf549f54df377ce39771a9fb987e0b9f3ca59a71c\"\n    }\n  }\n]\n[]\n{\n  \"class_id\": \"alias-2a1ef1a8d7e0ad48955683d1\",\n  \"verdict\": \"NOT_AI\",\n  \"advisory_disposition\": \"ACTIVE\",\n  \"advisory_aliases\": [\n    {\n      \"id\": \"GHSA-r4gj-5m52-g5wh\",\n      \"state\": \"ACTIVE\"\n    },\n    {\n      \"id\": \"CVE-2026-101907\",\n      \"state\": \"ACTIVE\"\n    }\n  ],\n  \"advisory_ids\": [\n    \"GHSA-r4gj-5m52-g5wh\",\n    \"CVE-2026-101907\"\n  ],\n  \"bug_semantics\": \"Authorization-bypass / confused-deputy: the redirect-limiting control maxRedirects is silently ignored by the fetch adapter, so a request the caller believes is redirect-constrained follows a 302 to a reachable-only-internally target (CWE-441, CWE-601).\",\n  \"mechanism\": \"In lib/adapters/fetch.js the fetch adapter destructures resolveConfig(config) without reading maxRedirects and builds the fetch options object without a redirect key, so the Fetch API default redirect:'follow' applies and a caller's maxRedirects:0 guard is bypassed. Requires an attacker-influenced redirect source (attacker server or open redirect), a caller that trusts maxRedirects:0, and the fetch adapter (explicit adapter:'fetch' or a runtime that resolves to fetch). The Node HTTP adapter is not affected: own('maxRedirects')===0 selects the native http/https transport.\",\n  \"introducer_sha\": \"a3ff99b59d8ec2ab5dd049e68c043617a4072e42\",\n  \"introducer_parent\": \"751133eb9ed794c6f6634c52f4fe116e33bf5f09\",\n  \"bic_granularity\": \"ATOMIC\",\n  \"bic_minimality\": \"ATOMIC\",\n  \"bic_note\": \"a3ff99b5 adds lib/adapters/fetch.js (blob cf1c6802) and registers it in knownAdapters and defaults.adapter; the introduced adapter never reads maxRedirects. Parent 751133eb has no lib/adapters/fetch.js and defaults.adapter=['xhr','http'], so parent/child comparison under identical conditions places the unconstrained redirect code path here. Atomic single feature. The published lower bound >=1.17.0 is contradicted as the origin: the omission is present at v1.16.1 and at v1.10.0, and no fetch-adapter redirect change exists at 1.17.0.\",\n  \"landing_commit\": null,\n  \"landing_basis\": \"INTRODUCER_ON_DEFAULT\",\n  \"landing_note\": \"a3ff99b5 is itself the squash-merged object on the default branch (single parent 751133eb, author Dmitriy Mozgovoy, committer GitHub <noreply@github.com>), so no distinct carrier object exists.\",\n  \"decomposed_shas\": [],\n  \"candidate_set\": [\n    \"a3ff99b59d8ec2ab5dd049e68c043617a4072e42\",\n    \"d1d359da347704e8b28d768e61515a3e96c5b072\",\n    \"1c7f6d76e58359daddf38a6e636dd801ffd9c61b\",\n    \"a04077a17db282c476c348e67994a95db2d015f6\"\n  ],\n  \"fix_sha\": \"d19040bda7a8be2f82c3c6e1a5bc03917daee39a\",\n  \"fix_granularity\": \"CARRIER_BUNDLE\",\n  \"atomic_repair_sha\": \"d19040bda7a8be2f82c3c6e1a5bc03917daee39a\",\n  \"fix_note\": \"d19040b (#11141) destructures maxRedirects and adds 'if (maxRedirects === 0) resolvedOptions.redirect = \\\"manual\\\"' (also on the safe second fetchOptions argument), closing the mechanism. #11141 is carrier-shaped (23 files; prototype-pollution, HTTP/2, proxy CIDR and data-URI work besides the fetch change), so the object is a bundle; the redirect repair was squash-collapsed into it and no separate member commit carries the fix content (git log -S maxRedirects -- lib/adapters/fetch.js yields only d19040b). v1.20.0 is the first release containing it.\",\n  \"fix\": \"d19040b (#11141) destructures maxRedirects and adds 'if (maxRedirects === 0) resolvedOptions.redirect = \\\"manual\\\"' (also on the safe second fetchOptions argument), closing the mechanism. #11141 is carrier-shaped (23 files; prototype-pollution, HTTP/2, proxy CIDR and data-URI work besides the fetch change), so the object is a bundle; the redirect repair was squash-collapsed into it and no separate member commit carries the fix content (git log -S maxRedirects -- lib/adapters/fetch.js yields only d19040b). v1.20.0 is the first release containing it.\",\n  \"fix_ai_marker\": {\n    \"state\": \"ABSENT\",\n    \"source\": \"commit\",\n    \"sha\": \"d19040bda7a8be2f82c3c6e1a5bc03917daee39a\",\n    \"scope\": \"empty commit body; committer GitHub <noreply@github.com>\"\n  },\n  \"ai_on_bic\": false,\n  \"ai_marker\": {\n    \"state\": \"ABSENT\",\n    \"source\": \"commit\",\n    \"sha\": \"a3ff99b59d8ec2ab5dd049e68c043617a4072e42\",\n    \"scope\": \"empty commit body; human author; no AI co-author trailer or tool disclosure\"\n  },\n  \"ai_evidence\": \"BIC a3ff99b5 author Dmitriy Mozgovoy <robotshara@gmail.com>, committer GitHub <noreply@github.com>, empty body. Branch member 1e5552ac (DigitalBrainJS, self-committed) and successor d1d359da have empty bodies. No AI marker in any local commit touching lib/adapters/fetch.js across all refs, including the fetched refs/pull/6371/head and refs/pull/6377/head.\",\n  \"identity_class\": \"human\",\n  \"disclosure_convention\": \"CONVENTION_NOT_OBSERVED\",\n  \"disclosure_convention_evidence\": \"At the BIC date (2024-04-28) the tree has no AGENTS.md and no .github/copilot-instructions.md; those files appear only in 2026 (commits 90ae1993, 3f83143b). No contemporaneous repo AI-disclosure convention applies.\",\n  \"remaining_gap\": null,\n  \"flip_condition\": \"Primary evidence that lib/adapters/fetch.js enforced maxRedirects or set redirect at some revision before the fix, or a distinct 1.17.0-or-later change that introduced or enlarged the fetch redirect exposure, would change the BIC and could change the verdict.\",\n  \"affected_versions\": \"advisory: >= 1.17.0, < 1.20.0; source omission present from v1.10.0\",\n  \"fixed_versions\": \"1.20.0\",\n  \"fixed_release\": \"v1.20.0\",\n  \"clone_head_sha\": \"e1a8a575\",\n  \"evidence\": [\n    {\n      \"path\": \"evidence/receipt_bic_intro.txt\",\n      \"sha256\": \"2cb3da595f992eb5c8243e336db97520ab0062da98f671f3f46cd12a9abbfc30\",\n      \"note\": \"BIC metadata, parent, parent-lacks-fetch.js, parent defaults.adapter\"\n    },\n    {\n      \"path\": \"evidence/receipt_omission_history.txt\",\n      \"sha256\": \"a4d8c5414f4291019b4c1b4c245d8ab33aaaa35aa25b2c85433a76f2123065fe\",\n      \"note\": \"per-tag grep proving the omission; -S histories; --find-object carriers\"\n    },\n    {\n      \"path\": \"evidence/receipt_fix.txt\",\n      \"sha256\": \"8df1fbae2c1cab0d03100ac5f11b86fdcde87ba08b4b97511285a533230af108\",\n      \"note\": \"fix metadata, containing tag v1.20.0, redirect hunk\"\n    },\n    {\n      \"path\": \"evidence/receipt_advisory.txt\",\n      \"sha256\": \"0256be4c43008e10f08f6b641e049219d28385d2d10cbee86c1929f1d0ac7942\",\n      \"note\": \"retained GHSA/CVE lifecycle and version range\"\n    },\n    {\n      \"path\": \"evidence/receipt_pr_probe.txt\",\n      \"sha256\": \"3a13cfe1e51c6f76344f3e7b42b4752c45fbb8b871ea7630f99472c494062449\",\n      \"note\": \"bounded PR-ref fetch and branch-level AI-marker scan\"\n    }\n  ],\n  \"reasoning\": \"Step 0: both advisories are ACTIVE (GHSA published_at set, withdrawn_at null; CVE published, not rejected). Step 1: the fetch adapter omits maxRedirects and the redirect option; the HTTP adapter enforces it via the native transport, matching the advisory. Step 2: the omission enters with the fetch adapter itself (a3ff99b5), not at 1.17.0. Step 3: d19040b adds redirect:'manual' for maxRedirects:0 and ships in v1.20.0. Step 4: the causal object has a recovered named human identity, no AI marker, and no contemporaneous disclosure convention. No AI-attributed contribution to the defect.\",\n  \"verdict_basis\": \"NOT_AI because the causal object (a3ff99b5) carries a named human identity (Dmitriy Mozgovoy <robotshara@gmail.com>), no AI marker, and the repo had no AI disclosure convention at that date. The defect is a human-authored omission of maxRedirects handling in a new adapter.\"\n}\n","exit_code":0,"status":"completed"}}
