{"type":"item.completed","item":{"id":"item_20","type":"command_execution","command":"/usr/bin/zsh -lc \"numactl --cpunodebind=1 --membind=1 /bin/sh -c 'sed -n \\\"1,130p\\\" contract/scripts/audit_reduction_gate.py; sed -n \\\"235,285p\\\" contract/scripts/audit_reduction_gate.py; sed -n \\\"1,150p\\\" contract/scripts/compare_slots.py'\"","aggregated_output":"#!/usr/bin/env python3\n\"\"\"Check a reducer's evidence-backed decisions against exact input/output bytes.\n\nThis checks delivery integrity, not the truth of a causal judgment. See\ndocs/ADJUDICATION-PROTOCOL.md. It never assembles records or writes the ledger.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport collections\nimport hashlib\nimport json\nfrom pathlib import Path\n\nfrom audit_record_gates import AI_VERDICTS, check_record, check_record_strict, load_record, review_signals\nfrom compare_slots import RESEARCH_FIELDS, lane_paths, load_snapshot, research_differences_many\n\nPIN_ROLES = ('manifest', 'audit_protocol', 'reducer_protocol', 'schema', 'brief',\n             'record_gate', 'comparison', 'reduction_gate')\nRESEARCH_CONTRACT = 'causal-work-v1'\nWORK_DIMENSIONS = tuple(name for name in RESEARCH_FIELDS if name != 'residual')\nTERMINAL_ROUTES = {'ANSWERED', 'UNAVAILABLE', 'EXHAUSTED', 'PROHIBITED'}\n\n\ndef text(value) -> bool:\n    return isinstance(value, str) and bool(value.strip())\n\n\ndef check_research_work(research, label, receipt):\n    \"\"\"Validate recorded work, not the completeness of source discovery or causal truth.\"\"\"\n    problems, worklist, boundaries = [], [], []\n    counts = collections.Counter()\n    if not isinstance(research, dict):\n        return [f'{label}: research needs an object'], counts, worklist, boundaries\n    if set(research) != set(WORK_DIMENSIONS):\n        problems.append(f'{label}: research needs exactly {list(WORK_DIMENSIONS)}')\n\n    def evidence(value, where):\n        if not isinstance(value, list) or not value:\n            problems.append(f'{where}: needs retained evidence receipts')\n        else:\n            for item in value:\n                receipt(item, where)\n\n    for dimension in WORK_DIMENSIONS:\n        if dimension not in research:\n            continue\n        detail = research[dimension]\n        where = f'{label} research {dimension}'\n        if not isinstance(detail, dict):\n            problems.append(f'{where}: needs an object')\n            continue\n        grade, state = detail.get('evidence_grade'), detail.get('work_state')\n        if grade not in ('BOUND', 'QUALIFIED_BOUNDARY', 'UNRESOLVED'):\n            problems.append(f'{where}: invalid evidence_grade')\n        if state not in ('COMPLETE', 'UNFINISHED'):\n            problems.append(f'{where}: invalid work_state')\n        if not text(detail.get('finding')):\n            problems.append(f'{where}: needs the supported finding and its scope')\n        evidence(detail.get('evidence'), where)\n        if grade != 'BOUND' and not text(detail.get('missing_fact')):\n            problems.append(f'{where}: an unbound conclusion needs missing_fact')\n        if grade == 'BOUND' and detail.get('missing_fact') is not None:\n            problems.append(f'{where}: BOUND cannot retain a decisive missing_fact')\n        routes = detail.get('routes')\n        if not isinstance(routes, list):\n            problems.append(f'{where}: routes must be a list')\n            routes = []\n        route_ids, identities, pending = set(), set(), set()\n        for route in routes:\n            if not isinstance(route, dict):\n                problems.append(f'{where}: each route must be an object')\n                continue\n            route_id = route.get('id')\n            if not text(route_id) or route_id in route_ids:\n                problems.append(f'{where}: route IDs must be nonempty and unique')\n                continue\n            route_ids.add(route_id)\n            identity = tuple(route.get(key) for key in ('question', 'source', 'evidence_type'))\n            if not all(text(part) for part in identity):\n                problems.append(f'{where} route {route_id}: needs question, source and evidence_type')\n            else:\n                identity = tuple(part.strip() for part in identity)\n                if identity in identities:\n                    problems.append(f'{where}: duplicate evidence route {route_id}')\n                identities.add(identity)\n            outcome = route.get('status')\n            if outcome in ('PENDING', 'FAILED'):\n                pending.add(route_id)\n            elif not text(outcome) or outcome not in TERMINAL_ROUTES:\n                problems.append(f'{where} route {route_id}: invalid status')\n            if outcome != 'PENDING':\n                if not text(route.get('observation')):\n                    problems.append(f'{where} route {route_id}: needs its actual observation')\n                evidence(route.get('evidence'), f'{where} route {route_id}')\n        next_route = detail.get('next_permitted_route')\n        if state == 'COMPLETE':\n            counts['COMPLETE'] += 1\n            if pending or 'next_permitted_route' not in detail or next_route is not None:\n                problems.append(f'{where}: COMPLETE contradicts unfinished routes or a next route')\n            if grade != 'BOUND':\n                boundaries.append(dimension)\n                if not routes:\n                    problems.append(f'{where}: an unbound COMPLETE finding needs a recorded evidence frontier')\n        elif state == 'UNFINISHED':\n            counts['UNFINISHED'] += 1\n            if not text(next_route) or next_route not in pending:\n                problems.append(f'{where}: UNFINISHED needs a next_permitted_route naming a PENDING or FAILED route')\n            worklist.append({'dimension': dimension, 'next_permitted_route': next_route})\n    return problems, counts, worklist, boundaries\n\n\ndef digest(path: Path) -> str:\n    return hashlib.sha256(path.read_bytes()).hexdigest()\n\n\ndef manifest_ids(path: Path) -> set[str]:\n    ids = []\n    for line in path.read_text().splitlines():\n        if not line.strip():\n            continue\n        value = load_record(line).get('class_id') if line.lstrip().startswith('{') else line.strip()\n        if not isinstance(value, str) or not value.strip():\n            raise ValueError('manifest: each row needs a class_id')\n        ids.append(value)\n    if not ids or len(ids) != len(set(ids)):\n        raise ValueError('manifest: empty or duplicate case IDs')\n    return set(ids)\n\n\n            problems.append(f'{cid}: digest bindings must include exactly all auditor inputs and accepted')\n        for name, (records, hashes) in snapshots.items():\n            if records[cid].get('class_id') != cid:\n                problems.append(f'{cid}: {name} record needs its explicit class_id')\n            if not text(records[cid].get('verdict')):\n                problems.append(f'{cid}: {name} verdict must be a nonempty string')\n            if not isinstance(bound, dict) or bound.get(name) != hashes[cid]:\n                problems.append(f'{cid}: {name} digest missing or changed since adjudication')\n        problems.extend(check_record(final) + check_record_strict(final))\n        status = decision.get('status')\n        counts[str(status)] += 1\n        if status == 'BLOCKED':\n            if not text(decision.get('next_question')):\n                problems.append(f'{cid}: BLOCKED needs the next decisive question')\n            problems.append(f'{cid}: research remains BLOCKED')\n        elif status != 'ACCEPTED':\n            problems.append(f'{cid}: status must be ACCEPTED or BLOCKED')\n        elif final.get('verdict') in ('EVIDENCE_GAP', 'BLOCKED'):\n            problems.append(f'{cid}: an open verdict cannot be research ACCEPTED')\n        if not text(decision.get('basis')):\n            problems.append(f'{cid}: needs the reducer\\'s whole-chain acceptance basis')\n        reviewed = decision.get('reviewed_dimensions')\n        if not isinstance(reviewed, list) or set(map(str, reviewed)) != set(RESEARCH_FIELDS):\n            problems.append(f'{cid}: explicitly review every research dimension')\n        required = set(research_differences_many({**inputs, 'accepted': final}))\n        all_records = [*inputs.values(), final]\n        # Agreement does not waive primary-evidence scrutiny on publication-sensitive claims.\n        if any(text(r.get('verdict')) and r['verdict'] in AI_VERDICTS for r in all_records):\n            required.update(('bic', 'ai', 'fix'))\n        if any(review_signals(r) for r in all_records):\n            required.add('residual')\n        if any(check_record(r) + check_record_strict(r) for r in inputs.values()):\n            required.add('input_quality')\n        resolutions = decision.get('resolutions')\n        if not isinstance(resolutions, dict):\n            resolutions = {}\n        if contract == RESEARCH_CONTRACT:\n            required.update(resolutions)\n        for dimension in sorted(required):\n            resolution = resolutions.get(dimension)\n            if contract == RESEARCH_CONTRACT:\n                if not isinstance(resolution, dict):\n                    problems.append(f'{cid}: unresolved {dimension}; needs structured claims, observation, reasoning and conclusion')\n                    continue\n                claims = resolution.get('claims')\n                if not isinstance(claims, dict) or set(claims) != set(paths) or not all(text(v) for v in claims.values()):\n                    problems.append(f'{cid}: {dimension} claims must account for every assigned lane')\n                for key in ('observation', 'reasoning', 'conclusion'):\n                    if not text(resolution.get(key)):\n                        problems.append(f'{cid}: {dimension} resolution needs {key}')\n                if not isinstance(resolution.get('evidence'), list) or not resolution['evidence']:\n#!/usr/bin/env python3\n\"\"\"Compare independent audit slots over the same batch.\n\nTwo blind audits of one batch disagree where the two briefs asked for\ndifferent fields, or where a rule lived only in prose. This prints that\ncomparison, so the drift is one command instead of a hand diff.\n\nUsage:\n  python3 scripts/compare_slots.py --lane auditor1=PATH --lane auditor2=PATH --lane auditor3=PATH\n  python3 scripts/compare_slots.py --a research/<batch>/review \\\\\n      --b research/<batch>/verify/cases [--json report.json] [--probe-git]\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport collections\nimport hashlib\nimport json\nimport os\nimport re\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\nfrom audit_record_gates import AI_VERDICTS, check_record, check_record_strict, load_record, review_signals\n\nSKIP = re.compile(r\"INDEX|manifest|selection|summary|excluded\", re.I)\nSQUASH_SUBJECT = re.compile(r\"\\(#\\d+\\)$\")\nFLAG_KINDS = (\n    (\"advisory_dead_vs_verdict\", \"but verdict is\"),\n    (\"advisory_disposition\", \"advisory_disposition\"),\n    (\"atomic_vs_landing\", \"is its own landing commit\"),\n    (\"bic_granularity\", \"bic_granularity\"),\n    (\"squash_decomposition\", \"SQUASH_DECOMPOSED requires\"),\n    (\"decomposition_probe\", \"AGGREGATE_MEMBERS_UNREACHABLE requires\"),\n    (\"non_git_boundary\", \"NON_GIT_BOUNDARY requires\"),\n    (\"flip_condition\", \"requires flip_condition\"),\n    (\"fix_ai_marker\", \"fix_ai_marker.state\"),\n    (\"ai_on_bic_type\", \"ai_on_bic must be a JSON boolean\"),\n    (\"ai_verdict_marker\", \"needs ai_on_bic true\"),\n    (\"not_ai_vs_ai_on_bic\", \"NOT_AI contradicts\"),\n)\nGIT_ENV = {**os.environ, \"GIT_NO_LAZY_FETCH\": \"1\"}\n\n# Text differences are review obligations, not machine-decided contradictions.\n# Keep distinct roles distinct: a landing is not an atomic member, and a later\n# AI contribution is not a decomposed BIC member.\nRESEARCH_FIELDS = {\n    'advisory': ('verdict', 'advisory_ids', 'advisory_disposition',\n                 'advisory_aliases', 'false_positive_ground'),\n    'mechanism': ('cause', 'mechanism', 'mechanisms', 'bug_semantics',\n                  'flaw_origin', 'counterevidence', 'evidence', 'reasoning'),\n    'bic': ('introducer_sha', 'introducer_parent', 'bic_granularity',\n            'bic_minimality', 'bic_note', 'landing_commit', 'landing_basis',\n            'landing_note', 'decomposed_shas', 'decomposition_probe'),\n    'ai': ('ai_on_bic', 'ai_marker', 'ai_admissibility', 'identity_class',\n           'disclosure_convention', 'disclosure_convention_evidence',\n           'candidate_set', 'candidate_details', 'carrier_set', 'ai_evidence'),\n    'fix': ('fix_sha', 'direct_fix_sha', 'atomic_repair_sha', 'fix_shas',\n            'minimum_fix_set', 'fix_granularity', 'fix', 'fix_note',\n            'fix_ai_marker', 'fix_chain', 'ir_chain', 'unpatched', 'potential_fix'),\n    'versions': ('versions', 'affected_versions', 'fixed_versions',\n                 'fixed_release', 'clone_head_sha'),\n    'residual': ('remaining_gap', 'residual_triage', 'flip_condition'),\n}\n\n\ndef research_differences_many(records: dict[str, dict]) -> dict:\n    \"\"\"List differing claims from every lane without choosing a preferred report.\"\"\"\n    first = next(iter(records.values()))\n    return {\n        dimension: {field: {name: record.get(field) for name, record in records.items()}\n                    for field in fields\n                    if any(record.get(field) != first.get(field) for record in records.values())}\n        for dimension, fields in RESEARCH_FIELDS.items()\n        if any(record.get(field) != first.get(field)\n               for field in fields for record in records.values())\n    }\n\n\ndef research_differences(a: dict, b: dict) -> dict:\n    return research_differences_many({'a': a, 'b': b})\n\n\ndef lane_paths(values=None, a: Path | None = None, b: Path | None = None) -> dict[str, Path]:\n    if values:\n        if a is not None or b is not None:\n            raise ValueError('use --lane or --a/--b, not both')\n        paths = {}\n        for value in values:\n            name, separator, path = value.partition('=')\n            if not separator or not path or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_-]*', name):\n                raise ValueError('--lane requires NAME=PATH')\n            if name == 'accepted' or name in paths:\n                raise ValueError(f'duplicate or reserved lane name: {name}')\n            paths[name] = Path(path)\n    elif a is not None and b is not None:\n        paths = {'a': a, 'b': b}\n    else:\n        raise ValueError('supply named --lane inputs, or both --a and --b')\n    if len({path.resolve() for path in paths.values()}) != len(paths):\n        raise ValueError('independent lanes must have distinct input paths')\n    return paths\n\n\ndef load_snapshot(path: Path) -> tuple[dict[str, dict], dict[str, str]]:\n    files = sorted(path.rglob('*.json')) if path.is_dir() else [path]\n    records: dict[str, dict] = {}\n    digests = {}\n    for file in files:\n        if SKIP.search(file.name):\n            continue\n        try:\n            data = file.read_bytes()\n            record = load_record(data.decode('utf-8'))\n        except (ValueError, UnicodeDecodeError) as exc:\n            raise ValueError(f\"{file}: {exc}\") from exc\n        if isinstance(record, dict) and 'verdict' in record:\n            key = str(record.get('class_id') or file.stem)\n            if key in records:\n                raise ValueError(f'{file}: duplicate class_id {key}')\n            records[key] = record\n            digests[key] = hashlib.sha256(data).hexdigest()\n    return records, digests\n\n\ndef load(path: Path) -> dict[str, dict]:\n    return load_snapshot(path)[0]\n\n\ndef sha(value) -> str:\n    return str(value).lower() if isinstance(value, str) and value.strip() else ''\n\n\ndef view(record: dict) -> dict:\n    \"\"\"One shape for both slots: new fields win, older ones map onto them.\"\"\"\n    members = record.get('decomposed_shas') or []\n    return {\n        'verdict': record.get('verdict'),\n        'bic': sha(record.get('introducer_sha')),\n        'fix': sha(record.get('fix_sha')) or sha(record.get('direct_fix_sha')),\n        'landing': sha(record.get('landing_commit')),\n        'members': [sha(m) for m in members if isinstance(m, str) and sha(m)],\n        'flip': bool(str(record.get('flip_condition') or '').strip())\n        or bool(re.search(r'\\bflip', str(record.get('reasoning') or ''), re.I)),\n        'ai_on_bic': record.get('ai_on_bic')\n        if isinstance(record.get('ai_on_bic'), bool)\n        else None,\n        'gap': str(record.get('remaining_gap') or '').strip(),\n","exit_code":0,"status":"completed"}}
