d7408ec3b12bf5f\",\n      \"hooks/pre-applypatch.sample\": \"e15c5b469ea3e0a695bea6f2c82bcf8e62821074939ddd85b77e0007ff165475\",\n      \"hooks/pre-push.sample\": \"ecce9c7e04d3f5dd9d8ada81753dd1d549a9634b26770042b58dda00217d086a\",\n      \"hooks/commit-msg.sample\": \"1f74d5e9292979b573ebd59741d46cb93ff391acdd083d340b94370753d92437\",\n      \"hooks/prepare-commit-msg.sample\": \"e9ddcaa4189fddd25ed97fc8c789eca7b6ca16390b2392ae3276f0c8e1aa4619\",\n      \"hooks/pre-commit.sample\": \"f9af7d95eb1231ecf2eba9770fedfa8d4797a12b02d7240e98d568201251244a\",\n      \"hooks/post-update.sample\": \"81765af2daef323061dcbc5e61fc16481cb74b3bac9ad8a174b186523586f6c5\",\n      \"hooks/pre-rebase.sample\": \"4febce867790052338076f4e66cc47efb14879d18097d1d61c8261859eaaa7b3\",\n      \"hooks/pre-merge-commit.sample\": \"d3825a70337940ebbd0a5c072984e13245920cdf8898bd225c8d27a6dfc9cb53\",\n      \"hooks/sendemail-validate.sample\": \"44ebfc923dc5466bc009602f0ecf067b9c65459abfe8868ddc49b78e6ced7a92\",\n      \"objects/pack/pack-531a5f0fee83fde5c1114ce71a5a9e6552cad161.rev\": \"129c239b883b5ad0adbd3f9b05a3b2627145ab78f4ebfe960ac09f7f0dd95358\",\n      \"objects/pack/pack-531a5f0fee83fde5c1114ce71a5a9e6552cad161.idx\": \"082328e00751365605eb29b36c1c974844f7904def5dd3d42351976c83e52988\",\n      \"objects/pack/pack-531a5f0fee83fde5c1114ce71a5a9e6552cad161.pack\": \"0c701bb80778dfe9e3aa6ad3ad6e730427c4d9a0f9008b8216deeee3c3780bf0\"\n    }\n  }\n]\n{\n  \"ghsa_id\": \"GHSA-qw65-cvwx-89v3\",\n  \"cve_id\": \"CVE-2026-84292\",\n  \"url\": \"https://api.github.com/advisories/GHSA-qw65-cvwx-89v3\",\n  \"html_url\": \"https://github.com/advisories/GHSA-qw65-cvwx-89v3\",\n  \"summary\": \"fast-uri vulnerable to authority injection via an unvalidated port in serialize\",\n  \"description\": \"### Impact\\n\\n`fast-uri` serializes the `port` component of a URI without validating it. When recomposing the authority, `fast-uri` escapes the userinfo and host components but concatenates the port verbatim, so a `port` value that is not a sequence of digits can inject authority delimiters. For example, serializing a component whose `port` is `@127.0.0.1:8124` produces `http://trusted.example:@127.0.0.1:8124/app`, demoting the intended host to userinfo and pointing the authority at an attacker-controlled host. Both `fast-uri` and Node's `URL` read the result back as the attacker's host with no error, so re-validating the built URI does not catch it.\\n\\nThis affects applications that build URIs from parts and assign untrusted data to the `port` component (for example a fixed host from configuration and a port taken from user input or a service record). The same path is reachable through `serialize()`, `normalize()`, and `equal()` in their object forms. A `port` obtained from `parse()` is always digits and is not affected.\\n\\n### Patches\\n\\nThis vulnerability has been patched in fast-uri `4.1.4`, `3.1.7`, and `2.4.6`. `recomposeAuthority` now rejects any port that is not `*DIGIT` per RFC 3986. All users should upgrade.\\n\\n### Workarounds\\n\\nIf upgrading is not immediately possible, validate the `port` value against the RFC 3986 grammar (digits only) before passing a component to `serialize()`, `normalize()`, or `equal()`, and reject anything else, for example `if (!/^\\\\d*$/.test(String(port))) throw new Error('invalid port')`.\",\n  \"type\": \"reviewed\",\n  \"severity\": \"high\",\n  \"repository_advisory_url\": \"https://api.github.com/repos/fastify/fast-uri/security-advisories/GHSA-qw65-cvwx-89v3\",\n  \"source_code_location\": \"https://github.com/fastify/fast-uri\",\n  \"identifiers\": [\n    {\n      \"value\": \"GHSA-qw65-cvwx-89v3\",\n      \"type\": \"GHSA\"\n    },\n    {\n      \"value\": \"CVE-2026-84292\",\n      \"type\": \"CVE\"\n    }\n  ],\n  \"references\": [\n    \"https://github.com/fastify/fast-uri/security/advisories/GHSA-qw65-cvwx-89v3\",\n    \"https://nvd.nist.gov/vuln/detail/CVE-2026-84292\",\n    \"https://github.com/fastify/fast-uri/commit/820e8478dd7da3d09f187bfaf35d50b71f67b8b4\",\n    \"https://cna.openjsf.org/security-advisories.html\",\n    \"https://github.com/fastify/fast-uri/releases/tag/v2.4.6\",\n    \"https://github.com/fastify/fast-uri/releases/tag/v3.1.7\",\n    \"https://github.com/fastify/fast-uri/releases/tag/v4.1.4\",\n    \"https://github.com/advisories/GHSA-qw65-cvwx-89v3\"\n  ],\n  \"published_at\": \"2026-09-28T21:24:39Z\",\n  \"updated_at\": \"2026-09-28T21:24:40Z\",\n  \"github_reviewed_at\": \"2026-09-28T21:24:39Z\",\n  \"nvd_published_at\": \"2026-09-02T20:17:39Z\",\n  \"withdrawn_at\": null,\n  \"vulnerabilities\": [\n    {\n      \"package\": {\n        \"ecosystem\": \"npm\",\n{\"dataType\":\"CVE_RECORD\",\"dataVersion\":\"5.2\",\"cveMetadata\":{\"cveId\":\"CVE-2026-84292\",\"assignerOrgId\":\"ce714d77-add3-4f53-aff5-83d477b104bb\",\"state\":\"PUBLISHED\",\"assignerShortName\":\"openjs\",\"dateReserved\":\"2026-09-01T16:10:49.688Z\",\"datePublished\":\"2026-09-02T20:09:51.415Z\",\"dateUpdated\":\"2026-09-03T13:16:25.237Z\"},\"containers\":{\"cna\":{\"providerMetadata\":{\"orgId\":\"ce714d77-add3-4f53-aff5-83d477b104bb\",\"shortName\":\"openjs\",\"dateUpdated\":\"2026-09-02T20:09:51.415Z\"},\"descriptions\":[{\"lang\":\"en\",\"value\":\"fast-uri serializes the port component of a URI without validating it. When recomposing the authority, the userinfo and host components are escaped but the port is concatenated verbatim, so a port value that is not a sequence of digits can inject authority delimiters, demoting the intended host to userinfo and pointing the authority at an attacker-controlled host. Both fast-uri and Node's URL read the result back as the attacker's host with no error, so re-validating the built URI does not catch it. This affects applications that build URIs from parts and assign untrusted data to the port component through the serialize, normalize, or equal functions in their object forms. The issue affects fast-uri versions before 2.4.6, from 3.0.0 before 3.1.7, and from 4.0.0 before 4.1.4. It is fixed in 2.4.6, 3.1.7, and 4.1.4, where recomposeAuthority rejects any port that is not a digit sequence per RFC 3986.\",\"supportingMedia\":[{\"type\":\"text/html\",\"base64\":false,\"value\":\"fast-uri serializes the port component of a URI without validating it. When recomposing the authority, the userinfo and host components are escaped but the port is concatenated verbatim, so a port value that is not a sequence of digits can inject authority delimiters, demoting the intended host to userinfo and pointing the authority at an attacker-controlled host. Both fast-uri and Node's URL read the result back as the attacker's host with no error, so re-validating the built URI does not catch it. This affects applications that build URIs from parts and assign untrusted data to the port component through the serialize, normalize, or equal functions in their object forms. The issue affects fast-uri versions before 2.4.6, from 3.0.0 before 3.1.7, and from 4.0.0 before 4.1.4. It is fixed in 2.4.6, 3.1.7, and 4.1.4, where recomposeAuthority rejects any port that is not a digit sequence per RFC 3986.\"}]}],\"affected\":[{\"vendor\":\"fast-uri\",\"product\":\"fast-uri\",\"defaultStatus\":\"unaffected\",\"versions\":[{\"versionType\":\"semver\",\"status\":\"affected\",\"version\":\"0\",\"lessThan\":\"2.4.6\"},{\"versionType\":\"semver\",\"status\":\"unaffected\",\"version\":\"2.4.6\"},{\"versionType\":\"semver\",\"status\":\"affected\",\"version\":\"3.0.0\",\"lessThan\":\"3.1.7\"},{\"versionType\":\"semver\",\"status\":\"unaffected\",\"version\":\"3.1.7\"},{\"versionType\":\"semver\",\"status\":\"affected\",\"version\":\"4.0.0\",\"lessThan\":\"4.1.4\"},{\"versionType\":\"semver\",\"status\":\"unaffected\",\"version\":\"4.1.4\"}],\"packageURL\":\"pkg:npm/fast-uri\"}],\"references\":[{\"url\":\"https://github.com/fastify/fast-uri/security/advisories/GHSA-qw65-cvwx-89v3\"},{\"url\":\"https://cna.openjsf.org/security-advisories.htm