lems.append(f'{label}: {exc}')\n\n    if not text(index.get('reducer')):\n        problems.append('reducer: name the sole accountable owner')\n    auditors = index.get('auditors')\n    if (not isinstance(auditors, list) or not auditors or not all(text(name) for name in auditors)\n            or len(auditors) != len(set(auditors))):\n        problems.append('auditors: freeze a unique list of all assigned lane names')\n    elif set(auditors) != set(paths):\n        problems.append(f'auditors: supplied lanes {sorted(paths)} differ from assigned lanes {sorted(auditors)}')\n    pins = index.get('pins')\n    if not isinstance(pins, dict):\n        pins = {}\n    for role in sorted(set(PIN_ROLES) | set(pins)):\n        receipt(pins.get(role), f'pin {role}')\n    runtime_files = {'manifest': manifest, 'record_gate': Path(__file__).with_name('audit_record_gates.py'),\n                     'comparison': Path(__file__).with_name('compare_slots.py'),\n                     'reduction_gate': Path(__file__)}\n    for role, path in runtime_files.items():\n        pin = pins.get(role)\n        actual = digest(path)\n        if path.resolve() in observed and observed[path.resolve()] != actual:\n            problems.append(f'pin {role}: changed while checking')\n        observed[path.resolve()] = actual\n        if isinstance(pin, dict) and pin.get('sha256') != actual:\n            problems.append(f'pin {role}: differs from the input or code used for this check')\n\n    roots = {**paths, 'accepted': accepted}\n    snapshots = {name: load_snapshot(path) for name, path in roots.items()}\n    cases = index.get('cases')\n    if not isinstance(cases, dict):\n        raise ValueError('decisions need a cases object keyed by class_id')\n    contract = index.get('research_contract')\n    if contract == RESEARCH_CONTRACT and any(\ndef check_git_evidence(record: dict, repo: Path) -> list[str]:\n    \"\"\"Verify object facts; admission of an AI contribution remains a research judgment.\"\"\"\n    cid = record.get(\"class_id\", \"?\")\n    problems = []\n    objects = {}\n    env = {**os.environ, \"GIT_NO_LAZY_FETCH\": \"1\", \"GIT_NO_REPLACE_OBJECTS\": \"1\"}\n\n    def read_commit(sha):\n        if not isinstance(sha, str) or not SHA40.fullmatch(sha):\n            problems.append(f\"{cid}: git: expected a full commit SHA, got {sha!r}\")\n            return None\n        if sha in objects:\n            return objects[sha]\n        try:\n            proc = subprocess.run(\n                [\"git\", \"--no-replace-objects\", \"-C\", str(repo), \"cat-file\", \"--batch\"],\n                input=sha + \"\\n\", capture_output=True, text=True, timeout=30, env=env,\n            )\n        except (OSError, UnicodeError, subprocess.SubprocessError) as exc:\n            problems.append(f\"{cid}: git: cannot read {sha}: {exc}\")\n            objects[sha] = None\n            return None\n        header, _, body = proc.stdout.partition(\"\\n\")\n        fields = header.split()\n        if proc.returncode or len(fields) != 3:\n            problems.append(f\"{cid}: git: commit {sha} unavailable in {repo}; recover evidence or record the gap\")\n            objects[sha] = None\n        elif fields[:2] != [sha, \"commit\"]:\n            problems.append(f\"{cid}: git: {sha} is not the named commit object\")\n            objects[sha] = None\n        else:\n            objects[sha] = body.removesuffix(\"\\n\")\n        return objects[sha]\n\n    intro = record.get(\"introducer_sha\")\n    if intro:\n        raw = read_commit(intro)\n        parent = record.get(\"introducer_parent\")\n        if raw is not None and parent:\n            parents = re.findall(r\"^parent ([0-9a-f]{40})$\", raw.partition(\"\\n\\n\")[0], re.M)\n            if parent not in parents:\n                problems.append(f\"{cid}: git: introducer_parent is not a parent of {intro}\")\n\n    for field in (\"ai_marker\", \"fix_ai_marker\"):\n        marker = record.get(field)\n        required = field == \"ai_m