le. Frozen protocol requires BLOCKED when atomic members remain unrecovered. Neither human bundle metadata nor unmerged AI proposals settles contribution-level attribution.\",\n  \"evidence\": [\n    {\n      \"path\": \"evidence/pin-verification.stdout\",\n      \"sha256\": \"53071d8946bad44916e018ec74997e814d2f1ff0ec97561db0c9740fe2e6fcc7\"\n    },\n    {\n      \"path\": \"evidence/00-github.json\",\n      \"sha256\": \"4b9ecc19637da305f04714a0ef4d7a30ba679ca0e68a136185867b16763d3055\"\n    },\n    {\n      \"path\": \"evidence/cve.stdout\",\n      \"sha256\": \"e0680af68449a0a2595db284c8707ed99d57048b103cdb29d78b2c8b66e87067\"\n    },\n    {\n      \"path\": \"evidence/origins.stdout\",\n      \"sha256\": \"14b9bb03721466f2590dac07df3a7bf9b1f3abac01b4b240390d6a1f307470e0\"\n    },\n    {\n      \"path\": \"evidence/historical-source.stdout\",\n      \"sha256\": \"6552fc4ebfc9268c71b72cefe82056850e550a7029633f3c107ed323569984df\"\n    },\n    {\n      \"path\": \"evidence/origin-history-probe.receipt.json\",\n      \"sha256\": \"24e27db622602358c83238e11085425ab8487f5f8bbcf7051d2380967446e698\"\n    },\n    {\n      \"path\": \"evidence/object-coverage.stdout\",\n      \"sha256\": \"53dcc3abaabb60714a5805023a5e3a06df349b931abc0a9a9a08e4296e240b88\"\n    },\n    {\n      \"path\": \"evidence/causal-comparisons.stdout\",\n      \"sha256\": \"c21e1236272da03ec90f796be94ecaeb1c22b257e0139c28fba657d0447fb43f\"\n    },\n    {\n      \"path\": \"evidence/exact-blob-carriers.json\",\n      \"sha256\": \"8412871c83eb6fe28f5099749ee5d2745060d67f16ba68d31637ac74284e007f\"\n    },\n    {\n      \"path\": \"evidence/main-repair.stdout\",\n      \"sha256\": \"2ef58b00078ce2e22abb3d080958fab07fcf3f7e8fd57e0787ad84e8c73fceb1\"\n    },\n    {\n      \"path\": \"evidence/ai-backport-132.stdout\",\n      \"sha256\": \"71980c1777ca58a1d645a6499e4014b74e6eab38bc855bb1ca0001a90c6d9a8c\"\n    },\n    {\n      \"path\": \"evidence/ai-backport-133.stdout\",\n      \"sha256\": \"e91771b5e