d) != set(roots):\n            problems.append(f'{cid}: digest bindings must include exactly all auditor inputs and accepted')\n        for name, (records, hashes) in snapshots.items():\n            if records[cid].get('class_id') != cid:\n                problems.append(f'{cid}: {name} record needs its explicit class_id')\n            if not text(records[cid].get('verdict')):\n                problems.append(f'{cid}: {name} verdict must be a nonempty string')\n            if not isinstance(bound, dict) or bound.get(name) != hashes[cid]:\n                problems.append(f'{cid}: {name} digest missing or changed since adjudication')\n        problems.extend(check_record(final) + check_record_strict(final))\n        status = decision.get('status')\n        counts[str(status)] += 1\n        if status == 'BLOCKED':\n            if not text(decision.get('next_question')):\n                problems.append(f'{cid}: BLOCKED needs the next decisive question')\n            problems.append(f'{cid}: research remains BLOCKED')\n        elif status != 'ACCEPTED':\n            problems.append(f'{cid}: status must be ACCEPTED or BLOCKED')\n        elif final.get('verdict') in ('EVIDENCE_GAP', 'BLOCKED'):\n            problems.append(f'{cid}: an open verdict cannot be research ACCEPTED')\n        if not text(decision.get('basis')):\n            problems.append(f'{cid}: needs the reducer\\'s whole-chain acceptance basis')\n        reviewed = decision.get('reviewed_dimensions')\n        if not isinstance(reviewed, list) or set(map(str, reviewed)) != set(RESEARCH_FIELDS):\n            problems.append(f'{cid}: explicitly review every research dimension')\n        required = set(research_differences_many({**inputs, 'accepted': final}))\n        all_records = [*inputs.values(), final]\n        # Agreement does not waive primary-evidence scrutiny on publication-sensitive claims.\n        if any(text(r.get('verdict')) and r['verdict'] in AI_VERDICTS for r in all_records):\n            required.update(('bic', 'ai', 'fix'))\n        if any(review_signals(r) for r in all_records):\n            required.add('residual')\n        if any(check_record(r) + check_record_strict(r) for r in inputs.values()):\n            required.add('input_quality')\n        resolutions = decision.get('resolutions')\n        if not isinstance(resolutions, dict):\n            resolutions = {}\n        if contract == RESEARCH_CONTRACT:\n            required.update(resolutions)\n        for dimension in sorted(required):\n            resolution = resolutions.get(dimension)\n            if contract == RESEARCH_CONTRACT:\n                if not isinstance(resolution, dict):\n                    problems.append(f'{cid}: unresolved {dimension}; needs structured claims, observation, reasoning and conclusion')\n                    continue\n                claims = resolution.get('claims')\n                if not isinstance(claims, dict) or set(claims) != set(paths) or not all(text(v) for v in claims.values()):\n                    problems.append(f'{cid}: {dimension} claims must account for every assigned lane')\n                for key in ('observation', 'reasoning', 'conclusion'):\n                    if not text(resolution.get(key)):\n                        problems.append(f'{cid}: {dimension} resolution needs {key}')\n                if not isinstance(resolution.get('evidence'), list) or not resolution['evidence']:\n                    problems.append(f'{cid}: {dimension} resolution needs primary receipts')\n                else:\n                    for item in resolution['evidence']:\n                        receipt(item, f'{cid} {dimension} resolution evidence')\n            elif not text(resolution):\n                problems.append(f'{cid}: unresolved {dimension}; explain the competing readings and evidence')\n        evidence = decision.get('evidence')\n        if not isinstance(evidence, list) or not evidence:\n            problems.append(f'{cid}: retain primary evidence receipts')\n        else:\n            for item in evidence:\n                receipt(item, f'{cid} evidence')\n\n    # Detect concurrent mutation and added/removed cases during the check itself.\n    for name, path in roots.items():\n        if load_snapshot(path)[1] != snapshots[name][1]:\n            problems.append(f'{name}: records changed while checking')\n    if decisions.read_bytes() != decision_bytes:\n        problems.append('decisions changed while checking')\n    for path, original in observed.items():\n        try:\n            if digest(path) != original:\n                problems.append(f'{path}: changed while checking')\n        except OSError as exc:\n            problems.append(str(exc))\n    return {'cases': len(expected), 'auditors': list(paths), 'research_status': dict(counts),\n            'research_work': {'contract': contract, 'checked': contract == RESEARCH_CONTRACT,\n                              'dimension_counts': dict(work_counts),\n                              'worklist': worklist, 'evidence_boundaries': boundaries,\n                              'unassessed_cases': unassessed_work,\n                              'scope': 'declared work only; route discovery and causal truth require review'},\n            'delivery_valid': not problems, 'problems': problems,\n            'decisions_sha256': hashlib.sha256(decision_bytes).hexdigest(),\n            'scope': 'delivery integrity; causal truth and publication require separate review'}\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser(description=__doc__)\n    for name in ('manifest', 'accepted', 'decisions'):\n        parser.add_argument('--' + name, required=True, type=Path)\n    parser.add_argument('--lane', action='append', help='NAME=PATH; repeat for all assigned auditors')\n    parser.add_argument('--a', type=Path, help='legacy input named a')\n    parser.add_argument('--b', type=Path, help='legacy input named b')\n    parser.add_argument('--research-contract', choices=[RESEARCH_CONTRACT],\n                        help='require the explicitly adopted research-work contract')\n    args = parser.parse_args()\n    try:\n        paths = lane_paths(args.lane, args.a, args.b)\n        report = check_delivery(args.manifest, args.accepted, args.decisions, lanes=paths,\n                                research_contract=args.research_contract)\n    except (OSError, ValueError) as exc:\n        parser.error(str(exc))\n    print(json.dumps(report, indent=2, sort_keys=True))\n    return 0 if report['delivery_valid'] else 1\n\n{\n  \"ghsa_id\": \"GHSA-qhr7-859c-m2p7\",\n  \"cve_id\": \"CVE-2026-102278\",\n  \"url\": \"https://api.github.com/advisories/GHSA-qhr7-859c-m2p7\",\n  \"html_url\": \"https://github.com/advisories/GHSA-qhr7-859c-m2p7\",\n  \"summary\": \"brace-expansion: DoS via uncontrolled recursion on nested brace groups causing stack exhaustion\",\n  \"description\": \"### Summary\\n\\n`expand_()` recurses once per level of brace *nesting*. Deeply nested input exhausts the native stack and crashes the process.\\n\\nThis is distinct from CVE-2026-14257 / GHSA-mh99-v99m-4gvg, which made the *tail* iterative (recursion on `m.post`, driven by how many groups are chained). Nesting depth drives a different recursion that the tail fix never touched, so the documented constant-stack-depth guarantee only ever covered chained input, not nested input.\\n\\nIt is also distinct from GHSA-6j4f-fj2g-mc7p, which fixed recursion in `parseCommaParts()`. Both payloads below still crash with that fix applied.\\n\\n### Two recursion sites\\n\\n**Comma members.** Each alternative of a brace set is expanded by a recursive call, so nesting a set inside every alternative recurses once per level:\\n\\n```js\\nexpand('{a,'.repeat(4000) + 'z' + '}'.repeat(4000))\\n// RangeError: Maximum call stack size exceeded\\n```\\n\\nCrashes at depth 3,907 - about **15.6 KB** of input.\\n\\n**Single set.** A brace set whose body parses to a single part is expanded by a recursive call before being re-wrapped (`x{{a,b}}y` -> `x{a}y x{b}y`), which recurses once per nesting level:\\n\\n```js\\nexpand('{'.repeat(3200) + 'a,b' + '}'.repeat(3200))\\n// RangeError: Maximum call stack size exceeded\\n```\\n\\nCrashes at depth 3,125 - about **6.25 KB** of input. This is the cheapest stack-exhaustion payload known against this package: roughly a quarter the input of GHSA-6j4f-fj2g-mc7p (29 KB), and about a tenth of minimatch's `MAX_PATTERN_LENGTH` (65,536).\\n\\n### Why `max` and `maxLength` do not help\\n\\nBoth crashes happen while recursing into sub-expansions, before the result set grows. The payloads produce almost no output - the single-set case yields 2 results - so neither bound is ever the limiter. `expand(payload, { max: 1, maxLength: 1 })` still overflows.\\n\\n### Impact\\n\\nAny application passing an untrusted string to `expand()`, directly or through `minimatch` / `glob` as a user-supplied glob pattern, can be crashed. In Node a `RangeError` the application does not catch terminates the process, so a server globbing user input is exposed to remote unauthenticated denial of service.\\n\\nAvailability only. No code execution, no data exposure.\\n\\n### Affected versions\\n\\nVerified affected on 1.1.18, 2.1.4, 3.0.6 and 5.0.9, at near-identical depths on every line (single set: 3,125 on all four; comma members: 3,907-4,102). Not a regression from any recent fix - the gap predates them.\\n\\n### Patch\\n\\nA `maxDepth` bound (default `EXPANSION_MAX_DEPTH`) is threaded through `expand_()`. Past the cap a group is treated as non-expanding and returned literally, which is how the parser already handles a group that cannot expand. This matches the existing `max` / `maxLength` caps, which truncate rather than throw, so `expand()` continues never to throw on any input.\\n\\nThe default sits far above any realistic nesting depth and well below the crash threshold.\",\n  \"type\": \"reviewed\",\n  \"severity\": \"high\",\n  \"repository_advisory_url\": \"https://api.github.com/repos/juliangruber/brace-expansion/security-advisories/GHSA-qhr7-859c-m2p7\",\n  \"source_code_location\": \"https://github.com/juliangruber/brace-expansion\",\n  \"identifiers\": [\n    {\n      \"value\": \"GHSA-qhr7-859c-m2p7\",\n      \"type\": \"GHSA\"\n    },\n    {\n      \"value\": \"CVE-2026-102278\",\n      \"type\": \"CVE\"\n    }\n  ],\n  \"references\": [\n    \"https://github.com/juliangruber/brace-expansion/security/advisories/GHSA-qhr7-859c-m2p7\",\n    \"https://nvd.nist.gov/vuln/detail/CVE-2026-102278\",\n    \"https://github.com/juliangruber/brace-expansion/commit/1efee7c397c191da6287a78ec19512476a966a7b\",\n    \"https://github.com/juliangruber/brace-expansion/commit/935d78f32f335b2ff76578e5c5e877d31ae9888c\",\n    \"https://github.com/juliangruber/brace-expansion/commit/de84f144e9816f30e25fc8179e2e1249ab6df0db\",\n    \"https://github.com/advisories/GHSA-qhr7-859c-m2p7\"\n  ],\n  \"published_at\": \"2026-09-29T23:45:17Z\",\n  \"updated_at\": \"2026-09-29T23:45:19Z\",\n  \"github_reviewed_at\": \"2026-09-29T23:45:17Z\",\n  \"nvd_published_at\": \"2026-09-28T21:17:16Z\",\n  \"withdrawn_at\": null,\n  \"vulnerabilities\": [\n    {\n      \"package\": {\n        \"ecosystem\": \"npm\",\n        \"name\": \"brace-expansion\"\n      },\n      \"vulnerable_version_range\": \">= 4.0.0, < 5.0.11\",\n      \"first_patched_version\": \"5.0.11\",\n      \"vulnerable_functions\": []\n    },\n    {\n      \"package\": {\n        \"ecosystem\": \"npm\",\n        \"name\": \"brace-expansion\"\n      },\n      \"vulnerable_version_range\": \">= 3.0.0, < 3.0.8\",\n      \"first_patched_version\": \"3.0.8\",\n      \"vulnerable_functions\": []\n    },\n    {\n      \"package\": {\n        \"ecosystem\": \"npm\",\n        \"name\": \"brace-expansion\"\n      },\n      \"vulnerable_version_range\": \">= 2.0.0, < 2.1.6\",\n      \"first_patched_version\": \"2.1.6\",\n      \"vulnerable_functions\": []\n    },\n    {\n      \"package\"