{"type":"item.completed","item":{"id":"item_30","type":"command_execution","command":"/usr/bin/zsh -lc \"numactl --cpunodebind=1 --membind=1 sh -c 'cat output/alias-31b59d85d0a2e70df260e6c1/evidence/root-source.stdout; cat output/alias-31b59d85d0a2e70df260e6c1/evidence/bundle-commit.stdout; sed -n \\\"1,180p\\\" output/alias-31b59d85d0a2e70df260e6c1/evidence/main-fix-source.stdout'\"","aggregated_output":"module.exports = expand;\n\nfunction expand(str) {\n  var ret = expandBraces(str);\n\n  for (var i = ret.length - 1; i >= 0; i--) {\n    ret.splice.apply(ret, [i, 1].concat(expandRanges(ret[i])));\n  }\n  return ret;\n}\n\nfunction expandBraces(str) {\n  var expansions = [];\n  var m = /{[^}]*}/g.exec(str);\n  if (!m) return [str];\n\n  var pre = expandBraces(m.input.substr(0, m.index));\n  var n = m[0].substr(1, m[0].length - 2).split(',');\n  var post = expandBraces(m.input.slice(m.index + m[0].length));\n\n  for (var i = 0; i < pre.length; i++) {\n    for (var j = 0; j < n.length; j++) {\n      for (var k = 0; k < post.length; k++) {\n        expansions.push([pre[i], n[j], post[k]].join(''))\n      }\n    }\n  }\n\n  return expansions;\n}\n\nfunction number(str) {\n  return parseInt(str, 10) == str\n    ? parseInt(str, 10)\n    : str.charCodeAt(0);\n}\n\nfunction expandRanges(str) {\n  var expansions = [];\n  var m = /\\[[^\\]]*\\]/g.exec(str);\n  if (!m) return [str];\n\n  var pre = expandRanges(m.input.substr(0, m.index));\n\n  var n = m[0].substr(1, m[0].length - 2).split('-');\n  var stringMode = /[a-z]/i.test(n[0]);\n  var start = number(n[0]);\n  var end = /\\:/.test(n[1])\n    ? number(n[1].split(':')[0])\n    : number(n[1]);\n  var step = /\\:/.test(n[1])\n    ? number(n[1].split(':')[1])\n    : 1;\n\n  var N = [];\n  function push(i) {\n    if (stringMode) N.push(String.fromCharCode(i))\n    else N.push(i);\n  }\n\n  for (var i = start; i <= end; i += step) push(i);\n  if (end - start % 2) push(end);\n\n  var post = expandRanges(m.input.slice(m.index + m[0].length));\n\n  for (var i = 0; i < pre.length; i++) {\n    for (var j = 0; j < N.length; j++) {\n      for (var k = 0; k < post.length; k++) {\n        expansions.push([pre[i], N[j], post[k]].join(''))\n      }\n    }\n  }\n\n  return expansions;\n}\n\ncommit 9a5bef783fad507aed02242ce726f89640bf42d1\nAuthor:     Julian Gruber <julian@juliangruber.com>\nAuthorDate: Sun Oct 13 14:56:58 2013 +0200\nCommit:     Julian Gruber <julian@juliangruber.com>\nCommitDate: Sun Oct 13 14:56:58 2013 +0200\n\n    ready for first publish\n---\n README.md                  | 121 ++++++++++++++++++++++++++++++++++++++++\n example.js                 |   6 +-\n index.js                   | 135 ++++++++++++++++++++++++++++-----------------\n package.json               |  17 +++---\n test/dollar.js             |   7 +++\n test/empty-option.js       |  10 ++++\n test/negative-increment.js |  15 +++++\n test/nested.js             |  16 ++++++\n test/order.js              |  10 ++++\n test/pad.js                |  13 +++++\n test/same-type.js          |   7 +++\n test/sequence.js           |  50 +++++++++++++++++\n 12 files changed, 346 insertions(+), 61 deletions(-)\n\ndiff --git a/README.md b/README.md\nnew file mode 100644\nindex 0000000..908d3a8\n--- /dev/null\n+++ b/README.md\n@@ -0,0 +1,121 @@\n+\n+# brace-expansion\n+\n+[Brace expansion](https://www.gnu.org/software/bash/manual/html_node/Brace-Expansion.html)\n+as known from sh/bash in JavaScript.\n+\n+## Example\n+\n+```js\n+var expand = require('brace-expansion');\n+\n+// expand comma seperated lists\n+console.log(expand('file-{a,b,c}.jpg'));\n+// => ['file-a.jpg', 'file-b.jpg', 'file-c'.jpg]\n+\n+console.log(expand('-v{,,}'));\n+// => ['-v', '-v', '-v']\n+\n+// expand ranges\n+console.log(expand('file{0..2}.jpg'));\n+// => ['file0.jpg', 'file1.jpg', 'file2.jpg']\n+\n+// characters work too\n+console.log(expand('file-{a..c}.jpg'));\n+// => ['file-a.jpg', 'file-b.jpg', 'file-c.jpg']\n+\n+// backwards iteration\n+console.log(expand('file{2..0}.jpg'));\n+// => ['file2.jpg', 'file1.jpg', 'file0.jpg']\n+\n+// custom increment values\n+console.log(expand('file{0..4..2}.jpg'));\n+// => ['file0.jpg', 'file2.jpg', 'file4.jpg']\n+\n+// also with characters\n+console.log(expand('file-{a..e..2}.jpg'));\n+// => ['file-a.jpg', 'file-c.jpg', 'file-e.jpg']\n+\n+// optional padding\n+console.log(expand('file{00..10..5}.jpg'));\n+// => ['file00.jpg', 'file05.jpg', 'file10.jpg']\n+\n+// nested expansion\n+console.log(expand('{{A..C},{a..c}}'));\n+// => ['A', 'B', 'C', 'a', 'b', 'c']\n+\n+console.log(expand('ppp{,config,oe{,conf}}'));\n+// => ['ppp', 'pppconfig', 'pppoe', 'pppoeconf']\n+```\n+\n+## API\n+\n+```js\n+var expand = require('brace-expansion');\n+```\n+\n+### var expanded = expand(str)\n+\n+Return an array of all possible and valid expansions of `str`. If none are\n+found, `[str]` is returned.\n+\n+Valid expansions are:\n+\n+```js\n+/^(.*,)+(.+)?$/\n+// {a,b,...}\n+```\n+\n+A comma seperated list of options, like `{a,b}` or `{a,{b,c}}` or `{,a,}`.\n+\n+```js\n+/^-?\\d+\\.\\.-?\\d+(\\.\\.-?\\d+)?$/\n+// {x..y[..incr]}\n+```\n+\n+A numeric sequence from `x` to `y` inclusive, with optional increment.\n+If `x` or `y` start with a leading `0`, all the numbers will be padded\n+to have equal length. Negative numbers and backwards iteration work too.\n+\n+```js\n+/^-?\\d+\\.\\.-?\\d+(\\.\\.-?\\d+)?$/\n+// {x..y[..incr]}\n+```\n+\n+An alphabetic sequence from `x` to `y` inclusive, with optional increment.\n+`x` and `y` must be exactly one character, and if given, `incr` must be a\n+number.\n+\n+For compatibility reasons, the string `${` is not eligible for brace expansion.\n+\n+## Installation\n+\n+With [npm](https://npmjs.org) do:\n+\n+```bash\n+npm install brace-expansion\n+```\n+\n+## License\n+\n+(MIT)\n+\n+Copyright (c) 2013 Julian Gruber &lt;julian@juliangruber.com&gt;\n+\n+Permission is hereby granted, free of charge, to any person obtaining a copy of\n+this software and associated documentation files