e \"\n        \"callback configuration.\"\n    )\n\n\ndef validate_no_callback_env_reference(\n    param: str, value: object, *, source: str\n) -> None:\n    if _is_env_reference(value):\n        _raise_env_reference_error(param, source=source)\n\n\n# Hardcoded list of supported callback params to avoid runtime inspection issues with TypedDict\n_supported_callback_params = [\n    \"langfuse_public_key\",\n    \"langfuse_secret\",\n    \"langfuse_secret_key\",\n    \"langfuse_host\",\n    \"langfuse_prompt_version\",\n    \"gcs_bucket_name\",\n    \"gcs_path_service_account\",\n    \"langsmith_api_key\",\n    \"langsmith_project\",\n    \"langsmith_base_url\",\n    \"langsmith_sampling_rate\",\n    \"langsmith_tenant_id\",\n    \"humanloop_api_key\",\n    \"arize_api_key\",\n    \"arize_space_key\",\n    \"arize_space_id\",\n    \"posthog_api_key\",\n    \"posthog_host\",\n    \"braintrust_api_key\",\n    \"braintrust_project\",\n    \"braintrust_host\",\n    \"slack_webhook_url\",\n    \"lunary_public_key\",\n]\n\n\ndef initialize_standard_callback_dynamic_params(\n    kwargs: Optional[Dict] = None,\n) -> StandardCallbackDynamicParams:\n    \"\"\"\n    Initialize the standard callback dynamic params from the kwargs\n\n    checks if langfuse_secret_key, gcs_bucket_name in kwargs and sets the corresponding attributes in StandardCallbackDynamicParams\n    \"\"\"\n\n    standard_callback_dynamic_params = StandardCallbackDynamicParams()\n    if kwargs:\n        # 1. Check top-level kwargs\n        for param in _supported_callback_params:\n            if param in kwargs:\n                _param_value = kwargs.get(param)\n                validate_no_callback_env_reference(\n                    param, _param_value, source=\"request body\"\n                )\n                standard_callback_dynamic_params[param] = _param_value  # type: ignore\n\n        # 2. Fallback: check \"metadata\" or \"litellm_params\" -> \"metadata\"\n        metadata = (kwargs.get(\"metadata\") or {}).copy()\n        litellm_params = kwargs.get(\"litellm_params\") or {}\n        if isinstance(litellm_params, dict):\n            metadata.update(litellm_params.get(\"metadata\") or {})\n\n        if isinstance(metadata, dict):\n            for param in _supported_callback_params:\n                if param not in standard_callback_dynamic_params and param in metadata:\n                    _param_value = metadata.get(param)\n                    validate_no_callback_env_reference(\n                        param, _param_value, source=\"metadata\"\n                    )\n                    standard_callback_dynamic_params[param] = _param_value  # type: ignore\n\n    return standard_callback_dynamic_params\n        valid_purposes = get_args(OpenAIFilesPurpose)\n        if purpose not in valid_purposes:\n            raise HTTPException(\n                status_code=400,\n                detail={\n                    \"error\": f\"Invalid purpose: {purpose}. Must be one of: {valid_purposes}\",\n                },\n            )\n        # Cast purpose to OpenAIFilesPurpose type\n        purpose = cast(OpenAIFilesPurpose, purpose)\n\n        data = {}\n\n        # Parse expires_after if provided\n        expires_after: Optional[FileExpiresAfter] = None\n        form_data_raw = await request.form()\n        form_data_dict: Dict[str, Any] = dict(form_data_raw)\n        extracted_litellm_metadata: Optional[Dict[str, Any]] = (\n            extract_nested_form_metadata(\n                form_data=form_data_dict, prefix=\"litellm_metadata[\"\n            )\n        )\n        expires_after_anchor = form_data_raw.get(\"expires_after[anchor]\")\n        expires_after_seconds_str = form_data_raw.get(\"expires_after[seconds]\")\n\n        # Add litellm_metadata to data if provided (from form field)\n        if extracted_litellm_metadata is not None:\n            data[\"litellm_metadata\"] = extracted_litellm_metadata\n\n        if expires_after_anchor is not None or expires_after