764397125e5807cce1e\"\n     data-url=\"/expressjs/morgan/security/advisories/GHSA-4vj7-5mj6-jm8m/show_partial?partial=repository_advisory%2Ftitle\"\n     >\n\n  <div class=\"gh-header issue js-repository-advisory-details\" >\n    <div class=\"gh-header-show\">\n\n      <h1 class=\"gh-header-title\" >\n        morgan vulnerable to Log Forging via unneutralized control characters in :remote-user\n      </h1>\n\n    </div>\n\n    <div class=\"gh-header-meta TableObject border-0 pb-0\">\n\n\n        <div class=\"TableObject-item\">\n          <span title=\"Severity: moderate\" data-view-component=\"true\" class=\"Label Label--warning Label--large text-bold mr-2 tmp-mr-2\">\n  Moderate\n</span>\n        </div>\n\n      <div class=\"TableObject-item TableObject-item--primary ws-normal\">\n          <a class=\"author Link--secondary text-bold\" data-hovercard-type=\"user\" data-hovercard-url=\"/users/UlisesGascon/hovercard\" data-octo-click=\"hovercard-link-click\" data-octo-dimensions=\"link_type:self\" href=\"/UlisesGascon\">UlisesGascon</a>\n          published\n          <span class=\"text-bold user-select-contain\">GHSA-4vj7-5mj6-jm8m</span>\n          <relative-time datetime=\"2026-06-02T19:45:33Z\" class=\"no-wrap\">Jun 2, 2026</relative-time>\n\n      </div>\n    </div>\n  </div>\n</div>\n\n\n    \n\n    <div class=\"d-flex flex-column flex-md-row\">\n      <div class=\"col-12 col-md-9\">\n  \n    <div class=\"Details js-details-container width-full\">\n  <div class=\"Details-content--shown\">\n      <div class=\"Box Box--responsive \">\n  <div class=\"Box-body\">\n        <div class=\"Bow-row border-0 clearfix \" >\n  <div class=\"float-left col-12 col-md-6 pr-md-2\">\n      <h2 class=\"text-small color-fg-muted mb-1\">Package</h2>\n\n    <div >\n        <span >\n          <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 28 28\" fill=\"none\" role=\"img\" aria-labelledby=\"abwsj1tze0zbwidunr2xt3y7j1dx1dl3\" class=\"octicon\" width=\"16\" height=\"16\"><title id=\"abwsj1tze0zbwidunr2xt3y7j1dx1dl3\">npm</title><path d=\"M25.943 0H2.057C.92 0 0 .92 0 2.057v23.886C0 27.08.92 28 2.057 28h23.886C27.08 28 28 27.08 28 25.943V2.057C28 .92 27.08 0 25.943 0z\" fill=\"#CB0000\"></path><path d=\"M5.964 22.365h8.082l.01-12.103h4.031l-.01 12.113h4.041l.01-16.143L5.985 6.21l-.021 16.154z\" fill=\"#fff\"></path></svg>\n\n        </span>\n      <span class=\"f4 color-fg-default text-bold\">morgan</span>        <span class=\"color-fg-muted f4 d-inline-flex text-underline\" >\n            (<a href=\"/advisories?query=ecosystem%3Anpm\" data-view-component=\"true\" class=\"Link Link--muted\">npm</a>)\n        </span>\n    </div>\n  </div>\n\n  <div class=\"float-left col-6 col-md-3 py-2 py-md-0 pr-2\">\n      <h2 class=\"text-small color-fg-muted mb-1\">Affected versions</h2>\n\n      <div class=\"f4 color-fg-default\" >&gt;= 1.2.0, &lt;= 1.10.1</div>\n  </div>\n\n  <div class=\"float-left col-6 col-md-3 py-2 py-md-0\">\n      <h2 class=\"text-small color-fg-muted mb-1\">Patched versions</h2>\n\n      <div class=\"f4 color-fg-default\" >&gt;= 1.11.0</div>\n  </div>\n</div>\n\n  </div>\n</div>\n\n\n    <div class=\"Box Box--responsive tmp-mt-3\">\n  <div class=\"Box-header color-bg-default border-bottom-0 \">\n  <h2 class=\"Box-title h5 color-fg-default\">Description</h2>\n</div>\n\n<div class=\"Box-body tmp-px-5 tmp-pb-5\">\n  <div class=\"markdown-body comment-body p-0\" >\n    <h3 dir=\"auto\">Impact</h3>\n<p dir=\"auto\">Morgan's <code class=\"notranslate\">:remote-user</code> token extracts the Basic auth username from the <code class=\"notranslate\">Authorization</code> header and writes it to the log stream without neutralizing control characters. An attacker can send a crafted <code class=\"notranslate\">Authorization: Basic</code> header containing CR/LF characters to inject forged log lines, corrupting the one-request-per-line structure of access logs.</p>\n<p dir=\"auto\">The built-in <code class=\"notranslate\">combined</code>, <code class=\"notranslate\">common</code>, <code class=\"notranslate\">default</code>, and <code class=\"notranslate\">short</code> formats are affected, as well as any custom format that includes <code class=\"notranslate\">:remote-user</code>.</p>\n<h3 dir=\"auto\">Patches</h3>\n<p dir=\"auto\">Users should upgrade to version 1.11.0.</p>\n<h3 dir=\"auto\">Workarounds</h3>\n<p dir=\"auto\">Use a custom format string that does not include <code class=\"notranslate\">:remote-user</code>.</p>\n  </div>\n</div>\n\n</div>\n\n  </div>\n</div>\n\n\n\n</div>\n\n  <div class=\"col-12 col-md-3 tmp-pl-md-4 tmp-mt-3 tmp-mt-md-0\">\n    <div class=\"discussion-sidebar-item js-repository-advisory-details\"  >\n  <h3 data-view-component=\"true\" class=\"mb-2 tmp-mb-2 f6\">Severity</h3>\n    <div data-view-component=\"true\" class=\"d-flex flex-items-baseline pb-1 tmp-pb-1\">\n    <span title=\"Severity: moderate\" data-view-component=\"true\" class=\"Label Label--warning\">\n  Moderate\n</span>\n\n    <div data-view-component=\"true\" class=\"lh-condensed d-flex flex-items-baseline ml-2 tmp-ml-2 color-fg-subtle f5\">\n      <div style=\"border-style: none none dashed !important;\" data-show-dialog-id=\"cvss-overall-score-id\" data-view-component=\"true\" class=\"color-fg-default text-semibold border-bottom\">\n        <button id=\"dialog-show-dialog-53bc8896-a744-4059-95f1-ad546b058310\" data-show-dialog-id=\"dialog-53bc8896-a744-4059-95f1-ad546b058310\" type=\"button\" data-view-component=\"true\" class=\"Button--link Button--medium Button color-fg-muted\">  <span class=\"Button-content\">\n    <span class=\"Button-label\">5.3</span>\n  </span>\n</button>\n\n<dialog-helper>\n  <dialog id=\"dialog-53bc8896-a744-4059-95f1-ad546b058310\" aria-modal=\"true\" aria-labelledby=\"dialog-53bc8896-a744-4059-95f1-ad546b058310-title\" aria-describedby=\"dialog-53bc8896-a744-4059-95f1-ad546b058310-description\" data-view-component=\"true\" class=\"Overlay Overlay-whenNarrow Overlay--size-sma