ription\": \"### Impact\\n\\nMorgan writes attacker-controlled request data to the access log. Its escaping (added in 1.11.0 and 1.12.0) neutralizes control characters, the Unicode line separators, and backslash, but not the double quote (`0x22`), which is the field delimiter of the Apache combined log format morgan emits. An attacker who controls a quoted field (`:user-agent`, `:referrer`, the request URL, or the Basic auth `:remote-user`) can inject a double quote to close the field early and forge additional fields in the log record. The `combined`, `common`, and `default` formats, and any custom format that quotes a token, are affected. This is an incomplete fix of CVE-2026-5078 and CVE-2026-15603.\\n\\n### Patches\\n\\nUsers should upgrade to version 1.12.1.\\n\\n### Workarounds\\n\\nUpdate to version 1.12.1.\",\n  \"type\": \"reviewed\",\n  \"severity\": \"medium\",\n  \"repository_advisory_url\": \"https://api.github.com/repos/expressjs/morgan/security-advisories/GHSA-9f6g-j8ch-79g4\",\n  \"source_code_location\": \"https://github.com/expressjs/morgan\",\n  \"identifiers\": [\n    {\n      \"value\": \"GHSA-9f6g-j8ch-79g4\",\n      \"type\": \"GHSA\"\n    },\n    {\n      \"value\": \"CVE-2026-87859\",\n      \"type\": \"CVE\"\n    }\n  ],\n  \"references\": [\n    \"https://github.com/expressjs/morgan/security/advisories/GHSA-9f6g-j8ch-79g4\",\n    \"https://nvd.nist.gov/vuln/detail/CVE-2026-87859\",\n    \"https://github.com/expressjs/morgan/commit/4b695edf967ce179cdf4009fe8cddd184b7511ee\",\n    \"https://cna.openjsf.org/security-advisories.html\",\n    \"https://github.com/expressjs/morgan/releases/tag/1.12.1\",\n    \"https://github.com/advisories/GHSA-9f6g-j8ch-79g4\"\n  ],\n  \"published_at\": \"2026-09-28T21:33:08Z\",\n  \"updated_at\": \"2026-09-28T21:33:10Z\",\n  \"github_reviewed_at\": \"2026-09-28T21:33:08Z\",\n  \"nvd_published_at\": \"2026-09-11T10:16:53Z\",\n  \"withdrawn_at\": null,\n  \"vulnerabilities\": [\n    {\n      \"package\": {\n        \"ecosystem\": \"npm\",\n        \"name\": \"morgan\"\n      },\n      \"vulnerable_version_range\": \"< 1.12.1\",\n      \"first_patched_version\": \"1.12.1\",\n      \"vulnerable_functions\": []\n    }\n  ],\n  \"cvss_severities\": {\n    \"cvss_v3\": {\n      \"vector_string\": \"CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:L/A:N\",\n      \"score\": 5.3\n    },\n    \"cvss_v4\": {\n      \"vector_string\": null,\n      \"score\": 0.0\n    }\n  },\n  \"cwes\": [\n    {\n      \"cwe_id\": \"CWE-117\",\n      \"name\": \"Improper Output Neutralization for Logs\"\n    }\n  ],\n  \"credits\": [\n    {\n      \"user\": {\n        \"login\": \"iRevivalx\",\n        \"id\": 55530196,\n        \"node_id\": \"MDQ6VXNlcjU1NTMwMTk2\",\n        \"avatar_url\": \"https://avatars.githubusercontent.com/u/55530196?v=4\",\n        \"gravatar_id\": \"\",\n        \"url\": \"https://api.github.com/users/iRevivalx\",\n        \"html_url\": \"https://github.com/iRevivalx\",\n        \"followers_url\": \"https://api.github.com/users/iRevivalx/followers\",\n        \"following_url\": \"https://api.github.com/users/iRevivalx/following{/other_user}\",\n        \"gists_url\": \"https://api.github.com/users/iRevivalx/gists{/gist_id}\",\n        \"starred_url\": \"https://api.github.com/users/iRevivalx/starred{/owner}{/repo}\",\n        \"subscriptions_url\": \"https://api.github.com/users/iRevivalx/subscriptions\",\n        \"organizations_url\": \"https://api.github.com/users/iRevivalx/orgs\",\n        \"repos_url\": \"https://api.github.com/users/iRevivalx/repos\",\n        \"events_url\": \"https://api.github.com/users/iRevivalx/events{/privacy}\",\n        \"received_events_url\": \"https://api.github.com/users/iRevivalx/received_events\",\n        \"type\": \"User\",\n        \"user_view_type\": \"public\",\n        \"site_admin\": false\n      },\n      \"type\": \"finder\"\n    },\n    {\n      \"user\": {\n        \"login\": \"UlisesGascon\",\n        \"id\": 5110813,\n        \"node_