a1c481ece410305d03a1f21c0b4a207\nAuthor:     Jeff Lindsay <progrium@gmail.com>\nAuthorDate: Thu Feb 24 12:28:20 2011 -0800\nCommit:     Jeff Lindsay <progrium@gmail.com>\nCommitDate: Thu Feb 24 12:28:20 2011 -0800\n\n    initial commit\n\ndiff --git a/jwt/__init__.py b/jwt/__init__.py\nnew file mode 100644\nindex 0000000..07850ad\n--- /dev/null\n+++ b/jwt/__init__.py\n@@ -0,0 +1,63 @@\n+\"\"\" JSON Web Token implementation\n+\n+Minimum implementation based on this spec:\n+http://self-issued.info/docs/draft-jones-json-web-token-01.html\n+\"\"\"\n+import base64\n+import hashlib\n+import hmac\n+\n+try:\n+    import json\n+except ImportError:\n+    import simplejson as json\n+    \n+__all__ = ['encode', 'decode', 'DecodeError']\n+\n+class DecodeError(Exception): pass\n+\n+signing_methods = {\n+    'HS256': lambda msg, key: hmac.new(key, msg, hashlib.sha256).hexdigest(),\n+    'HS384': lambda msg, key: hmac.new(key, msg, hashlib.sha384).hexdigest(),\n+    'HS512': lambda msg, key: hmac.new(key, msg, hashlib.sha512).hexdigest(),\n+}\n+\n+def base64url_decode(input):\n+    input += '=' * (4 - (len(input) % 4))\n+    return base64.urlsafe_b64decode(input)\n+\n+def base64url_encode(input):\n+    return base64.urlsafe_b64encode(input).replace('=', '')\n+\n+def encode(payload, key, algorithm='HS256'):\n+    segments = []\n+    header = {\"typ\": \"JWT\", \"alg\": algorithm}\n+    segments.append(base64url_encode(json.dumps(header)))\n+    segments.append(base64url_encode(json.dumps(payload)))\n+    signing_input = '.'.join(segments)\n+    try:\n+        signature = signing_methods[algorithm](signing_input, key)\n+    except KeyError:\n+        raise NotImplementedError(\"Algorithm not supported\")\n+    segments.append(base64url_encode(signature))\n+    return '.'.join(segments)\n+\n+def decode(jwt, key='', verify=True):\n+    try:\n+        signing_input, crypto_segment = jwt.rsplit('.', 1)\n+        header_segment, payload_segment = signing_input.split('.', 1)\n+    except ValueError:\n+        raise DecodeError(\"Not enough segments\")\n+    try:\n+        header = json.loads(base64url_decode(header_segment))\n+        payload = json.loads(base64url_decode(payload_segment))\n+        signature = base64url_decode(crypto_segment)\n+    except (ValueError, TypeError):\n+        raise DecodeError(\"Invalid segment encoding\")\n+    if verify:\n+        try:\n+            if not signature == signing_methods[header['alg']](signing_input, key):\n+                raise DecodeError(\"Signature verification failed\")\n+        except KeyError:\n+            raise DecodeError(\"Algorithm not supported\")\n+    return payload\n5fde08a6cf906aa7698de2d6391d88b73006b17b 2026-09-22T11:44:19-04:00 fix: normalize recursive JWT payload errors\n793a30279584fcf2db889363b0db1f6d38d74e97 2026-09-13T04:18:49+02:00 fix: raise PyJWTError (not TypeError) for non-numeric exp/nbf/iat claims (#1186)\n06573692ebcdec8831c3927513b3e87c31fbbb62 2026-09-09T13:26:32-04:00 Handle recursive JWS headers as decode errors\n74961f165765300dc6b366c6c2b3dc0d11b92bde 2026-02-03T02:18:50+00:00 fix: preserve microsecond precision in JWT time claims (exp, iat, nbf)\n2fc6aa3ffecb54325d44ef076d4eff7418e97a81 2022-12-08T11:51:24+02:00 Add PyJWT._{de,en}code_payload hooks (#829)\n8556a1590532d58c540256ae1824688ec6c7abe2 2020-05-15T03:44:22+02:00 Enhance tracebacks. (#477)\n3b14696763243942a89b22c5e894b06ddb02951c 2020-04-04T19:07:16-04:00 src layout, tox, gh actions\nddbaf0008eac6559da5ebd1f24f68ee99ccb34b0 2015-04-19T08:32:06-05:00 Refactored PyJWT._validate_claims into multiple PyJWT._validate_* submethods to eliminate a lot of complexity.\na3f2ec37f8660e3c445635ed417ae1100753309d 2015-04-19T08:12:07-05:00 Refactored JWS-specific logic out of PyJWT and into PyJWS superclass\n84582f45b30cdfa659309ac2fcf90f7341befbad 2015-03-29T09:54:22-05:00 Added validation for 'nbf' claim to ensure it is an int value. #121\n50059281ef0451dc70f2a191d4db563868be5a5d 2015-03-29T09:50:58-05:00 Added validation for 'iat' claim to ensure it is an int value. #121\n12a13fe6d9c90a5de9579269386ca077eeb25f1f 2015-03-29T09:42:55-05:00 Added validation for 'exp' claim to ensure it is an int value. #121\n4e024325715f1427f532b3376a2ffe28315a6ebc 2015-03-15T17:40:08-05:00 Refactored api.py so that all JWT functions are now part of a PyJWT class. - Created a singleton instance to preserve jwt.encode, jwt.decode,   jwt.register_algorithms existing public APIs - Renamed load and verify_signature to _load and _verify_signature since   they are not part of the existing public API - Modified related tests to use PyJWT._load and PyJWT._verify_signature\n5f255f94a6d8763cb7ae504348429f770f69be6e 2015-01-18T14:08:56-04:00 Cleanup __init__ module\n1da2d4a52d55d64f77d7c6d6b52cdba555dc0e0b 2015-01-06T08:00:28-06:00 Fixes #70. Refactored all HMAC, RSA, and EC code into seperate classes in the algorithms module Added register_algorithm to add new algorithms.\na517b0caa690126647fbdbc29db626c57d37975f 2014-12-18T17:54:25-06:00 Modified ECDSA algorithms to use cryptography library instead of ecdsa.\n524d9733ed5b963a0fe3b2efd0c0ddbf48ad744b 2014-12-07T23:39:07-06:00 Modified RSA algorithms to use cryptography library instead of PyCrypto\n0e8dcb32ef115676cd7b6a2402a221fad4820553 2013-05-15T13:57:08-07:00 Add decode segment errors\nab8821fefa1c481ece410305d03a1f21c0b4a207 2011-02-24T12:28:20-08:00 initial commit\ncommit 5fde08a6cf906aa7698de2d6391d88b73006b17b\nAuthor:     José Padilla <jpadilla@users.noreply.github.com>\nAuthorDate: Tue Sep 22 11:44:19 2026 -0400\nCommit:     José Padilla <jpadilla@users.noreply.github.com>\nCommitDate: Tue Sep 22 11:44:19 2026 -0400\n\n    fix: normalize recursive JWT payload errors\n\n jwt/api_jwt.py            |  2 +-\n tests/test_api_jwt.py     | 18 +++++++++++++++++-\n tests/test_jwks_client.py | 21 +++++++++++++++++++++\n 3 files changed, 39 insertions(+), 2 deletions(-)\ncommit 051ea341b5573fe3edcd53042f347929b92c2b92\nAuthor:     José Padilla <jpadilla@w