of file\ndiff --git a/README.md b/README.md\nnew file mode 100644\nindex 0000000..9debcfe\n--- /dev/null\n+++ b/README.md\n@@ -0,0 +1,41 @@\n+# PyJWT\n+A Python implementation of [JSON Web Token draft 01](http://self-issued.info/docs/draft-jones-json-web-token-01.html).\n+\n+## Installing\n+\n+    sudo easy_install PyJWT\n+\n+## Usage\n+\n+    import jwt\n+    jwt.encode({\"some\": \"payload\"}, \"secret\")\n+\n+Note the resulting JWT will not be encrypted, but verifiable with a secret key.\n+\n+    jwt.decode(\"someJWTstring\", \"secret\")\n+\n+If the secret is wrong, it will raise a `jwt.DecodeError` telling you as such. You can still get at the payload by setting the verify argument to false.\n+\n+    jwt.decode(\"someJWTstring\", verify=False)\n+\n+## Algorithms\n+\n+The JWT spec supports several algorithms for cryptographic signing. This library currently supports:\n+\n+* HS256\t- HMAC using SHA-256 hash algorithm (default)\n+* HS384\t- HMAC using SHA-384 hash algorithm\n+* HS512 - HMAC using SHA-512 hash algorithm\n+\n+Change the algorithm with by setting it in encode:\n+\n+    jwt.encode({\"some\": \"payload\"}, \"secret\", \"HS512\")\n+\n+## Tests\n+\n+You can run tests from the project root after installed with:\n+\n+    python tests/test_jwt.py\n+\n+## License\n+\n+MIT\n\\ No newline at end of file\ndiff --git a/jwt/__init__.py b/jwt/__init__.py\nnew file mode 100644\nindex 0000000..07850ad\n--- /dev/null\n+++ b/jwt/__init__.py\n@@ -0,0 +1,63 @@\n+\"\"\" JSON Web Token implementation\n+\n+Minimum implementation based on this spec:\n+http://self-issued.info/docs/draft-jones-json-web-token-01.html\n+\"\"\"\n+import base64\n+import hashlib\n+import hmac\n+\n+try:\n+    import json\n+except ImportError:\n+    import simplejson as json\n+    \n+__all__ = ['encode', 'decode', 'DecodeError']\n+\n+class DecodeError(Exception): pass\n+\n+signing_methods = {\n+    'HS256': lambda msg, key: hmac.new(key, msg, hashlib.sha256).hexdigest(),\n+    'HS384': lambda msg, key: hmac.new(key, msg, hashlib.sha384).hexdigest(),\n+    'HS512': lambda msg, key: hmac.new(key, msg, hashlib.sha512).hexdigest(),\n+}\n+\n+def base64url_decode(input):\n+    input += '=' * (4 - (len(input) % 4))\n+    return base64.urlsafe_b64decode(input)\n+\n+def base64url_encode(input):\n+    return base64.urlsafe_b64encode(input).replace('=', '')\n+\n+def encode(payload, key, algorithm='HS256'):\n+    segments = []\n+    header = {\"typ\": \"JWT\", \"alg\": algorithm}\n+    segments.append(base64url_encode(json.dumps(header)))\n+    segments.append(base64url_encode(json.dumps(payload)))\n+    signing_input = '.'.join(segments)\n+    try:\n+        signature = signing_methods[algorithm](signing_input, key)\n+    except KeyError:\n+        raise NotImplementedError(\"Algorithm not supported\")\n+    segments.append(base64url_encode(signature))\n+    return '.'.join(segments)\n+\n+def decode(jwt, key='', verify=True):\n+    try:\n+        signing_input, crypto_segment = jwt.rsplit('.', 1)\n+        header_segment, payload_segment = signing_input.split('.', 1)\n+    except ValueError:\n+        raise DecodeError(\"Not enough segments\")\n+    try:\n+        header = json.loads(base64url_decode(header_segment))\n+        payload = json.loads(base64url_decode(payload_segment))\n+        signature = base64url_decode(crypto_segment)\n+    except (ValueError, TypeError):\n+        raise DecodeError(\"Invalid segment encoding\")\n+    if verify:\n+        try:\n+            if not signature == signing_methods[header['alg']](signing_input, key):\n+                raise DecodeError(\"Signature verification failed\")\n+        except KeyError:\n+            raise DecodeError(\"Algorithm not supported\")\n+    return payload\ndiff --git a/setup.py b/setup.py\nnew file mode 100644\nindex 0000000..a3bfb56\n--- /dev/null\n+++ b/setup.py\n@@ -0,0 +1,23 @@\n+import os\n+from setuptools import setup\n+\n+def read(fname):\n+    return open(os.path.join(os.path.dirname(__file__), fname)).read()\n+\n+setup(\n+    name = \"PyJWT\",\n+    version = \"0.1.1\",\n+    author = \"Jeff Lindsay\",\n+    author_email = \"jeff.lindsay@twilio.com\",\n+    description = (\"JSON Web Token implemtnation in Python\"),\n+    license = \"MIT\",\n+    keywords = \"jwt json web token security signing\",\n+    url = \"http://github.com/progrium/pyjwt\",\n+    packages=['jwt', 'tests'],\n+    long_description=read('README.md'),\n+    classifiers=[\n+        \"Development Status :: 3 - Alpha\",\n+        \"Topic :: Utilities\",\n+        \"License :: OSI Approved :: MIT License\",\n+    ],\n+)\n\\ No newline at end of file\ndiff --git a/tests/test_jwt.py b/tests/test_jwt.py\nnew file mode 100644\nindex 0000000..017a3f4\n--- /dev/null\n+++ b/tests/test_jwt.py\n@@ -0,0 +1,48 @@\n+import unittest\n+import time\n+\n+import jwt\n+\n+class TestJWT(unittest.TestCase):\n+\n+    def setUp(self):\n+        self.payload = {\"iss\": \"jeff\", \"exp\": int(time.time()), \"claim\": \"insanity\"}\n+\n+    def test_encode_decode(self):\n+        secret = 'secret'\n+        jwt_message = jwt.encode(self.payload, secret)\n+        decoded_payload = jwt.decode(jwt_message, secret)\n+        self.assertEqual(decoded_payload, self.payload)\n+    \n+    def test_bad_secret(self):\n+        right_secret = 'foo'\n+        bad_secret = 'bar'\n+        jwt_message = jwt.encode(self.payload, right_secret)\n+        self.assertRaises(jwt.DecodeError, jwt.decode, jwt_message, bad_secret)\n+    \n+    def test_decodes_valid_jwt(self):\n+        example_payload = {\"hello\": \"world\"}\n+        example_secret = \"secret\"\n+        example_jwt = \"eyJhbGciOiAiSFMyNTYiLCAidHlwIjogIkpXVCJ9.eyJoZWxsbyI6ICJ3b3JsZCJ9.YjZmNmEwMmMzMmU4NmEyMjRhYzRlMmFhYTQxNWQyMTA2Y2JiNDk4NGEyN2Q5ODYzOWVkODI2ZjVjYjY5Y2EzZg\"\n+        decoded_payload = jwt.decode(example_jwt, example_secret)\n+        self.assertEqual(decoded_payload, example_payload)\n+    \n+    def test_allow_skip_verification(self):\n+        right_secret = 'foo'\n+        bad_secret = 'bar'\n+        jwt_message = jwt.encode(self.payload, right_secret)\n+        decoded_payload = jwt.decode(jwt_message, verify=False)\n+        self.assertEqual(decoded_payload, self.payload)\n+    \n+    def test_no_secret(self):\n+        right_secret = 'foo'\n+        bad_secret = 'bar'\n+        jwt_message = jwt.encode(self.payload, right_secret)\n+        self.assertRaises(jwt.DecodeError, jwt.decode, jwt_message)\n+    \n+    def test_invalid_crypto_alg(self):\n+        self.assertRaises(NotImplementedError, jwt.encode, self.payload, \"secret\", \"HS1024\")\n+    \n+\n+if __name__ == '__main__':\n+    unittest.main()\n\\ No newline at end of file\n4adcd02722f5011c60079d3978dfc167b9a8eaa5 2026-09-21T16:46:39+05:30 Aroh Maurya <aroh3006@gmail.com> Catch http.client.HTTPException in PyJWKClient.fetch_data (#1201)\n2763752196113e1473b0ed7905aa6034aedfbe53 2026-09-22T15:39:04+02:00 Nikita Karamov <me@kytta.dev> Add support for Python 3.15 (#1202)\nc9d4d5375bf464ef363506fed9eb6e7f33217ab6 2026-09-22T09:39:42-04:00 Charlie Tonneslan <cst0520@gmail.com> docs/conf: drop duplicate 'and' from read() docstring (#1174)\n171062d2d734315272a901100aa4b109f2fc3c19 2026-09-22T09:40:11-04:00 Charlie Tonneslan <cst0520@gmail.com> utils: mention bytes in force_bytes type error (#1173)\n5fde08a6cf906aa7698de2d6391d88b73006b17b 2026-09-22T11:44:19-04:00 José Padilla <jpadilla@users.noreply.github.com> fix: normalize recursive JWT payload errors\n9bc06658f875b9b40091539140bbbdc4639161c3 2026-09-23T09:32:36-04:00 José Padilla <jpadilla@users.noreply.github.com> fix: make recursive payload tests deterministic\n1d41a6478e1562e68ff667fcd703356acf085f68 2026-09-23T10:59:55-04:00 José Padilla <jpadilla@users.noreply.github.com> chore: prepare 2.15.0 release\n7bf32526738fe837387bdedd4849a4a525c33a79 2026-09-28T12:22:34-04:00 José Padilla <jpadilla@webapplicate.com> Accept canonical Base64URL padding in JWT segments (#1216)\n7d5ef55e42ce42221f58dc49943e