complete fix' refers to the historical 1.11.0/1.12.0 state.\",\n    \"evidence\": [\n      {\n        \"path\": \"evidence/receipt-fix-commit.txt\",\n        \"sha256\": \"69d69fe25c12125e7cd13d1f090db8662746234d1dbe0c1c07270cdd7d917ff0\"\n      },\n      {\n        \"path\": \"evidence/receipt-releases.txt\",\n        \"sha256\": \"8bfe9fac9a7598b5c7823e10cb392e47f8470d6998e1b70a7a41008b0989bb3d\"\n      }\n    ],\n    \"missing_fact\": null,\n    \"next_permitted_route\": null,\n    \"routes\": []\n  },\n  \"versions\": {\n    \"evidence_grade\": \"BOUND\",\n    \"work_state\": \"COMPLETE\",\n    \"finding\": \"morgan < 1.12.1 vulnerable, first patched 1.12.1; confirmed against released tags and HISTORY.md. Source-release scope only.\",\n    \"evidence\": [\n      {\n        \"path\": \"evidence/00-github.json\",\n        \"sha256\": \"4d0d2e2dca4a528495a84f270645604082343149993fb27cb3214d62e56b3a87\"\n      },\n      {\n        \"path\": \"evidence/receipt-releases.txt\",\n        \"sha256\": \"8bfe9fac9a7598b5c7823e10cb392e47f8470d6998e1b70a7a41008b0989bb3d\"\n      }\n    ],\n    \"missing_fact\": null,\n    \"next_permitted_route\": null,\n    \"routes\": []\n  }\n}","exit_code":0,"status":"completed"}}
