nchurch/subscriptions\",\n        \"organizations_url\": \"https://api.github.com/users/jonchurch/orgs\",\n        \"repos_url\": \"https://api.github.com/users/jonchurch/repos\",\n        \"events_url\": \"https://api.github.com/users/jonchurch/events{/privacy}\",\n        \"received_events_url\": \"https://api.github.com/users/jonchurch/received_events\",\n        \"type\": \"User\",\n        \"user_view_type\": \"public\",\n        \"site_admin\": false\n      },\n      \"type\": \"remediation_reviewer\"\n    }\n  ],\n  \"comments\": 6,\n  \"epss\": {\n    \"percentage\": 0.0041,\n    \"percentile\": 0.32535\n  }\n}\nHTTP/2 200 \r\ndate: Sun, 04 Oct 2026 18:11:36 GMT\r\ncontent-type: application/json; charset=utf-8\r\ncontent-length: 3997\r\naccess-control-allow-origin: *\r\ncontent-security-policy: default-src 'self';base-uri 'self';font-src 'self' https: data:;form-action 'self';frame-ancestors 'self';img-src 'self' data:;object-src 'none';script-src 'self';script-src-attr 'none';style-src 'self' https: 'unsafe-inline';upgrade-insecure-requests\r\ncross-origin-opener-policy: same-origin\r\ncross-origin-resource-policy: same-origin\r\norigin-agent-cluster: ?1\r\nreferrer-policy: no-referrer\r\nstrict-transport-security: max-age=15552000; includeSubDomains\r\nx-content-type-options: nosniff\r\nx-dns-prefetch-control: off\r\nx-download-options: noopen\r\nx-frame-options: SAMEORIGIN\r\nx-permitted-cross-domain-policies: none\r\nx-xss-protection: 0\r\ncache-control: no-store\r\nratelimit-policy: 25000;w=60\r\nratelimit-limit: 25000\r\nratelimit-remaining: 24667\r\nratelimit-reset: 54\r\netag: W/\"f9d-QoAwvUKbla0d/wjvB1dM/wOKHBk\"\r\n\r\n{\"dataType\":\"CVE_RECORD\",\"dataVersion\":\"5.2\",\"cveMetadata\":{\"cveId\":\"CVE-2026-87859\",\"assignerOrgId\":\"ce714d77-add3-4f53-aff5-83d477b104bb\",\"state\":\"PUBLISHED\",\"assignerShortName\":\"openjs\",\"dateReserved\":\"2026-09-09T13:05:45.895Z\",\"datePublished\":\"2026-09-11T09:15:19.109Z\",\"dateUpdated\":\"2026-09-11T11:32:10.246Z\"},\"containers\":{\"cna\":{\"providerMetadata\":{\"orgId\":\"ce714d77-add3-4f53-aff5-83d477b104bb\",\"shortName\":\"openjs\",\"dateUpdated\":\"2026-09-11T09:15:19.109Z\"},\"descriptions\":[{\"lang\":\"en\",\"value\":\"morgan is an HTTP request logger middleware for Node.js. In versions before 1.12.1, its escapeLogField() function does not escape the double quote character, which delimits the quoted fields of the Apache combined log format that morgan emits. An unauthenticated remote attacker who controls a value written to a quoted field, such as the User-Agent or Referer header, can include a double quote to close that field early, so a log consumer that parses the log by field position reads attacker-supplied text as the following field. In the built-in formats this makes the recorded value differ from the value that was sent, and in custom formats that quote an attacker-controlled token before a server-controlled one it can forge values such as the response status. No newline is injected, so record separation stays intact. The issue is fixed in morgan 1.12.1, which escapes the double quote. Users should upgrade to morgan 1.12.1 or later.\",\"supportingMedia\":[{\"type\":\"text/html\",\"base64\":false,\"value\":\"morgan is an HTTP request logger middleware for Node.js. In versions before 1.12.1, its escapeLogField() function does not escape the double quote character, which delimits the quoted fields of the Apache combined log format that morgan emits. An unauthenticated remote attacker who controls a value written to a quoted field, such as the User-Agent or Referer header, can include a double quote to close that field early, so a log consumer that parses the log by field position reads attacker-supplied text as the following field. In the built-in formats this makes the recorded value differ from the value that was sent, and in custom formats that quote an attacker-controlled token before a server-controlled one it can forge values such as the response status. No newline is injected, so record separation stays intact. The issue is fixed in morgan 1.12.1, which escapes the double quote. Users should upgrade to morgan 1.12.1 or later.\"}]}],\"affected\":[{\"vendor\":\"morgan\",\"product\":\"morgan\",\"defaultStatus\":\"unaffected\",\"versions\":[{\"versionType\":\"semver\",\"status\":\"affected\",\"version\":\"0\",\"lessThan\":\"1.12.1\"},{\"versionType\":\"semver\",\"status\":\"unaffected\",\"version\":\"1.12.1\"}],\"packageURL\":\"pkg:npm/morgan\"}],\"references\":[{\"url\":\"https://github.com/expressjs/morgan/security/advisories/GHSA-9f6g-j8ch-79g4\"},{\"url\":\"https://cna.openjsf.org/security-advisories.html\"}],\"credits\":[{\"lang\":\"en\",\"type\":\"finder\",\"value\":\"Alfie Goh Li Heng\"},{\"lang\":\"en\",\"type\":\"remediation developer\",\"value\":\"UlisesGascon\"},{\"lang\":\"en\",\"type\":\"remediation reviewer\",\"value\":\"jonchurch\"}],\"title\":\"morgan vulnerable to Log Injection via unescaped double quote in quoted log fields\",\"metrics\":[{\"format\":\"CVSS\",\"cvssV3_1\":{\"version\":\"3.1\",\"vectorString\":\"CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:L/A:N\",\"baseScore\":5.3,\"baseSeverity\":\"MEDIUM\"},\"scenarios\":[{\"lang\":\"en\",\"value\":\"GENERAL\"}]}],\"problemTypes\":[{\"descriptions\":[{\"cweId\":\"CWE-117\",\"lang\":\"en\",\"description\":\"CWE-117: Improper Output Neutralization for Logs\",\"type\":\"CWE\"}]}],\"x_generator\":{\"engine\":\"cve-kit 1.0.0\"}},\"adp\":[{\"metrics\":[{\"other\":{\"type\":\"ssvc\",\"content\":{\"timestamp\":\"2026-09-11T11:22:20.073554Z\",\"id\":\"CVE-2026-87859\",\"options\":[{\"Exploitation\":\"none\"},{\"Automatable\":\"yes\"},{\"Technical Impact\":\"partial\"}],\"role\":\"CISA Coordinator\",\"version\":\"2.0.3\"}}}],\"title\":\"CISA ADP Vulnrichment\",\"providerMetadata\":{\"orgId\":\"134c704f-9b21-4f2e-91b3-4a467353bcc0\",\"shortName\":\"CISA-ADP\",\"dateUpdated\":\"2026-09-11T11:32:10.246Z\"}}]}}","exit_code":0,"status":"completed"}}
